"""French Form Four Term One: thirty teaching rows; integration 16/32 excluded."""
import json
import sys
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
import lessonlib as L
import banks_fr as B
from french_figures import scene
L.use_class('form-4','Form 4')
OUT=L.ROOT/'french'
SRC=['francais']
PATH=[]
def F(term,meaning,case,error,why): return dict(term=term,meaning=meaning,case=case,error=error,why=why)
def item(q,r,w,y):
    assert len(w)==3
    return dict(q=q,r=r,w=[a for a,b in w],e=[b for a,b in w],y=y)
def qa(n,key,level,bank,**kw): return B.QA(f'fr4-{n}-{key}',level,'{X.q}',bank,SRC,**kw)
def choose(n,rows,key='appliquer',level=2):
    return qa(n,key,level,[item(q,r,list(zip(w,e)),y) for q,r,w,e,y in rows])
def unit(n,title,goal,back,onward,note,model,method,facts,applied,prereq=(),paper=None,extra=None,figure=None,example=None):
    assert 4<=len(facts)<=6
    defs=[]; cases=[]
    for i,f in enumerate(facts):
        others=[x for j,x in enumerate(facts) if j!=i][:3]
        defs.append(item('Quel terme désigne '+f['meaning']+' ?',f['term'],[(x['term'],'Cela désigne '+x['meaning']+', plutôt que la notion demandée.') for x in others],f['why']))
        cases.append(item(f['case']+'\nQuelle notion convient ?',f['term'],[(x['term'],'Cela concerne '+x['meaning']+'. Compare cette définition avec le cas présenté.') for x in others],f['why']))
    q0=qa(n,'notions',1,defs); q1=qa(n,'cas',1,cases)
    q3=extra or B.MT(f'fr4-{n}-relier',2,'Relie chaque notion à son exemple.',[(f['term'],f['case']) for f in facts],SRC,pick=3)
    q4=B.SP(f'fr4-{n}-corriger',3,'Repère la formulation ou l’affirmation incorrecte.',[f['term']+' : '+f['meaning']+'.' for f in facts],[(f['error'],f['why']) for f in facts],SRC)
    for st,f in zip(q4['pool']['right'],facts): st['explain']='Cette distinction est correcte : '+f['why']+' Cherche plutôt une phrase qui contredit le sens ou la règle.'
    sections=[('Ton objectif et les liens','À la fin, tu pourras '+goal+'. Acquis mobilisés : '+back+'. Pour la suite : '+onward+'.'),('Comprendre la règle ou le sens',note),('Lire le modèle original',model),('Appliquer et vérifier',method)]
    if figure: sections[2]=(*sections[2],figure)
    L.lesson('french','french',n,(f'fr4-{n}',title),prereq,note,
      example or L.worked({},facts[0]['case']+' Explique le choix.',[facts[0]['meaning']+'.',facts[0]['why']],facts[0]['term']),
      [L.card(f'fr4-{n}-c1','Distingue les notions avant de choisir.',[f['term']+' : '+f['meaning']+'.' for f in facts],q0['id']),
       L.card(f'fr4-{n}-c2','Lis le contexte avant de nommer la notion.',[f['case'] for f in facts],q1['id']),
       L.card(f'fr4-{n}-c3','Corrige sans changer le sens voulu.',[f['error']+' Correction : '+f['why'] for f in facts],q4['id'])],
      [q0,q1,applied,q3,q4],paper=paper,lang='fr',learn=L.learn(sections,key_words=[(f['term'],f['meaning']) for f in facts],mistake=(facts[0]['error'],facts[0]['meaning']+'.',facts[0]['why'])))
    PATH.append((n,title,goal,back,onward))

def conjugate(n,fn,tense,verbs):
    answer='fr2PasseCompose(v,p)' if fn=='fr2PasseCompose' else 'fr2With(p,'+fn+'(v,p))'
    if fn=='fr2PasseCompose':
        bad=[('{fr2PcOtherAux(v,p)}','aux'),('{fr2PcInfinitive(v,p)}','inf'),('{fr2With(p,fr2Present(v,p))}','temps')]
        misc=[('aux','Ce choix remplace l’auxiliaire de la forme active demandée.'),('inf','Après l’auxiliaire, emploie le participe passé, non l’infinitif.'),('temps','Cette forme est au présent simple, non au temps composé demandé.')]
    else:
        other='fr2Imparfait' if fn=='fr2PasseSimple' else 'fr2PasseSimple'
        bad=[('{fr2With(p,'+other+'(v,p))}','temps'),('{fr2PasseCompose(v,p)}','compose'),('{fr2With(p,v)}','inf')]
        misc=[('temps','Cette terminaison appartient à un autre temps ; conserve le temps demandé.'),('compose','Tu as choisi un temps composé au lieu de la forme simple demandée.'),('inf','L’infinitif ne porte pas l’accord personnel nécessaire ici.')]
    return B.mcq(f'fr4-{n}-conjuguer',2,'Conjugue « {v} » à l’indicatif {temps}, à la voix active, avec « {fr2Pronoun(p)} ».','{'+answer+'}',bad,
      ['Repère le sujet et le temps demandé.','La forme complète est {answer}.'],vars={'v':{'pick':verbs},'p':{'int':[0,7]},'temps':tense},misc=misc,sources=SRC)

unit(6,'Le passé simple : verbes des premier et deuxième groupes','former le passé simple étudié et distinguer un événement achevé d’un arrière-plan',
 'les sujets, les groupes verbaux et les récits de la classe précédente','l’enchaînement narratif et la comparaison avec le passé composé',
 'Le passé simple est surtout employé dans le récit écrit. Il présente notamment des événements achevés faisant avancer l’histoire, tandis que l’imparfait peut installer le décor ou une habitude. Les verbes réguliers en -er suivent un modèle en -ai, -as, -a, -âmes, -âtes, -èrent. Les verbes du deuxième groupe suivent -is, -is, -it, -îmes, -îtes, -irent. Certains changements orthographiques conservent le son du radical. Une forme doit toujours être lue avec son sujet et son contexte.',
 'Modèle original : Le soir était calme. Bih {fr2PasseSimple("parler",3)} au groupe, puis les élèves {fr2PasseSimple("finir",6)} leur affiche. Était calme fournit l’arrière-plan ; les événements suivants font progresser le récit. Compare {fr2With(4,fr2PasseSimple("aider",4))} et {fr2With(5,fr2PasseSimple("choisir",5))} : les marques personnelles et les accents ne sont pas interchangeables.',
 'Repère l’infinitif et le groupe, choisis la personne, puis vérifie la terminaison. Ne généralise pas le modèle de finir à tous les verbes en -ir. Écris ensuite une courte suite d’actions originale en conservant le même cadre narratif.',[
 F('événement narratif','un fait présenté comme achevé et faisant avancer le récit','Bih {fr2PasseSimple("parler",3)}, puis le groupe {fr2PasseSimple("finir",2)} son affiche.','Le passé simple décrit obligatoirement une habitude encore actuelle.','Il présente ici les événements accomplis de la narration.'),
 F('modèle en -er','les terminaisons régulières étudiées avec parler ou aider','{fr2With(4,fr2PasseSimple("aider",4))} porte une terminaison du modèle en -er.','Tous les groupes ont exactement les terminaisons de finir.','Le modèle dépend du groupe et du verbe.'),
 F('deuxième groupe','les verbes réguliers du type finir au modèle en -is','{fr2With(5,fr2PasseSimple("finir",5))} suit le modèle de finir.','Tout infinitif en -ir appartient automatiquement au deuxième groupe.','Des verbes comme partir ne suivent pas toute la conjugaison de finir.'),
 F('arrière-plan','les circonstances ou habitudes qui entourent les événements','Le soir était calme installe le cadre.','Tous les verbes d’un récit doivent être au même temps.','L’imparfait et le passé simple peuvent avoir des rôles complémentaires.')],conjugate(6,'fr2PasseSimple','passé simple',['parler','aider','finir','choisir']))

unit(10,'Le passé composé','former une forme active au passé composé et choisir l’auxiliaire et l’accord du modèle',
 'les événements narratifs et les participes déjà rencontrés','la traduction et la comparaison des temps du récit',
 'Le passé composé associe avoir ou être au présent à un participe passé. Il présente notamment un événement accompli dans un récit ou un échange. Le choix de l’auxiliaire dépend du verbe et parfois de son emploi. Avec être, les participes non pronominaux étudiés s’accordent avec le sujet. Avec avoir, ils ne s’accordent pas simplement avec le sujet ; les cas du complément direct placé avant demandent une analyse supplémentaire. Ne remplace pas le participe par l’infinitif.',
 'Modèle original : {fr2PasseCompose("aider",3)} une voisine. Puis {fr2PasseCompose("arriver",3)} au club. Dans la première forme, avoir porte la personne et le participe ne reçoit pas l’accord du sujet. Dans la seconde, être accompagne arriver et le féminin apparaît. Compare aussi {fr2PasseCompose("partir",7)} : le sujet féminin pluriel commande ici l’accord.',
 'Retrouve le sujet, le verbe et son emploi. Conjugue l’auxiliaire au présent, ajoute le participe, puis examine l’accord nécessaire. Garde la voix active demandée : une autre construction grammaticale ne répond pas forcément à cette consigne.',[
 F('auxiliaire','avoir ou être portant la conjugaison du temps composé','Dans {fr2PasseCompose("aider",3)}, l’auxiliaire est conjugué au présent.','L’auxiliaire doit toujours rester à l’infinitif.','La personne et le temps sont portés par l’auxiliaire conjugué.'),
 F('participe passé','la forme verbale associée à l’auxiliaire','Le participe de finir est {fr2Participle("finir")}.','Après a, le verbe doit toujours rester finir.','Le participe diffère de l’infinitif dans ce modèle.'),
 F('accord avec être','l’accord avec le sujet pour les verbes non pronominaux étudiés','{fr2PasseCompose("arriver",7)} comporte les marques du féminin pluriel.','Avec être, les participes étudiés restent toujours masculins singuliers.','Le sujet commande ici le genre et le nombre du participe.'),
 F('voix active demandée','une construction où le sujet est présenté comme agent dans le modèle','{fr2PasseCompose("aider",0)} une amie ne se confond pas avec une construction passive.','Changer de voix ne peut jamais changer le sens.','Le rôle du sujet et la construction doivent rester conformes à la demande.')],conjugate(10,'fr2PasseCompose','passé composé',['aider','finir','arriver','partir']),[6])

unit(15,'L’imparfait dans la narration','former l’imparfait et justifier son emploi dans un décor ou une habitude passée',
 'passé simple, passé composé et identification du sujet','la narration cohérente et les constructions de la suite du programme',
 'L’imparfait de l’indicatif présente notamment un état, une habitude ou une action envisagée dans son déroulement passé. Il ne signifie pas automatiquement qu’une action a réellement duré longtemps. Sa formation part généralement de la forme de nous au présent, sans -ons, puis ajoute -ais, -ais, -ait, -ions, -iez, -aient. Être a le radical ét-. Des ajustements orthographiques préservent certains sons. Le choix entre temps dépend du point de vue narratif et du contexte, pas seulement d’un mot isolé.',
 'Modèle original : Chaque soir, Bih {fr2Imparfait("aider",3)} son frère. La cour était calme. Un jour, elle {fr2PasseSimple("finir",3)} plus tôt. Le premier verbe présente une habitude ; le dernier présente l’événement achevé choisi par le récit. Compare {fr2With(4,fr2Imparfait("manger",4))} et {fr2With(0,fr2Imparfait("manger",0))} pour observer l’orthographe.',
 'Identifie la personne et le rôle du passage. Forme le radical puis la terminaison, sans oublier les changements nécessaires. Réemploie une forme dans une phrase originale et explique ce qu’elle présente comme arrière-plan ou habitude.',[
 F('habitude passée','une action répétée dans un cadre passé','Chaque soir, elle {fr2Imparfait("aider",3)} son frère.','L’imparfait ne peut jamais exprimer une répétition passée.','Le contexte chaque soir présente ici une habitude.'),
 F('état descriptif','une situation servant de cadre au récit','La cour était calme installe la scène.','Toute description est forcément un événement soudain au passé simple.','Un état peut fournir l’arrière-plan de la narration.'),
 F('formation personnelle','l’association d’un radical et de la terminaison exigée par le sujet','{fr2With(5,fr2Imparfait("finir",5))} porte la terminaison de vous.','La terminaison reste toujours celle de je.','Le sujet commande la marque personnelle.'),
 F('point de vue narratif','la manière de présenter un procès comme déroulement ou événement achevé','Le même récit combine décor à l’imparfait et événement au passé simple.','La durée réelle suffit toujours à choisir mécaniquement un temps.','Le contexte et la manière de présenter le fait comptent aussi.')],conjugate(15,'fr2Imparfait','imparfait',['aider','finir','manger','être']),[6,9,10])

subj=B.mcq('fr4-22-conjuguer',2,'Après « Il faut », choisis la suite avec « {fr2Pronoun(p)} » et « {v} » au subjonctif présent.','{fr2Que(p,fr2Subjonctif(v,p))}',
 [('{fr2Que(p,fr2Present(v,p))}','indicatif'),('{fr2Que(p,fr2FuturSimple(v,p))}','futur'),('{fr2Que(p,v)}','infinitif')],['La construction exige ici le subjonctif présent.','La suite est {answer}.'],vars={'v':{'pick':['être','avoir','faire','aller','finir','choisir']},'p':{'int':[0,7]}},where=['fr2Subjonctif(v,p) != fr2Present(v,p)'],misc=[('indicatif','Cette forme est à l’indicatif présent, différent dans ce cas.'),('futur','La construction demandée n’emploie pas ici le futur de l’indicatif.'),('infinitif','Un sujet exprimé après que demande ici une forme conjuguée.')],sources=SRC)
unit(22,'Le subjonctif présent : formation et emploi','former le subjonctif présent des verbes étudiés dans une construction de nécessité ou de souhait',
 'la phrase introduite par que et les formes de l’indicatif','la formulation d’avis, de souhaits et de consignes',
 'Le subjonctif est un mode employé dans certaines constructions, notamment après il faut que ou un verbe de volonté comme vouloir que. Le présent du subjonctif a souvent les terminaisons -e, -es, -e, -ions, -iez, -ent, mais plusieurs radicaux et verbes sont irréguliers. Être et avoir ont des formes particulières. Que ne déclenche pas toujours le subjonctif : je constate que présente habituellement un constat à l’indicatif. Lis l’expression qui commande la proposition.',
 'Modèle original : Il faut {fr2Que(4,fr2Subjonctif("finir",4))} l’affiche. Je souhaite {fr2Que(3,fr2Subjonctif("être",3))} prête. Compare avec je constate qu’elle est prête : la présence de que ne suffit donc pas à choisir le mode. Apprends la construction complète et vérifie le sujet.',
 'Repère l’expression de nécessité ou de volonté, puis le sujet de la subordonnée. Choisis la forme adaptée plutôt que d’ajouter que à un infinitif. Écris un souhait original avec un sujet différent de celui du verbe principal et vérifie les accords.',[
 F('nécessité','ce que la construction il faut que présente comme nécessaire','Il faut {fr2Que(4,fr2Subjonctif("faire",4))} attention.','Il faut que est toujours suivi d’un futur simple.','Dans le modèle étudié, cette construction commande le subjonctif.'),
 F('volonté ou souhait','une attitude pouvant commander une subordonnée au subjonctif','Je souhaite {fr2Que(3,fr2Subjonctif("aller",3))} au club.','Tout souhait après que se forme seulement avec un infinitif non conjugué.','Un sujet propre dans la subordonnée demande la construction adaptée.'),
 F('forme irrégulière','une forme ne suivant pas simplement le radical régulier attendu','{fr2Que(6,fr2Subjonctif("être",6))} comporte une forme particulière de être.','Tous les verbes gardent exactement le radical de parler.','Certains verbes exigent un apprentissage spécifique.'),
 F('choix du mode','la sélection dépendant de la construction et du sens','Je constate qu’elle est prête présente un constat.','Chaque que impose automatiquement le subjonctif.','Le mot introducteur seul ne décide pas de tous les emplois.')],subj,[13,15,18])

imper=B.mcq('fr4-29-conjuguer',2,'Forme l’impératif présent de « {v} », à la personne correspondant à « {fr2ImperPerson(k)} », sans pronom sujet.','{fr2Imperatif(v,k)}',
 [('{fr2Imperatif(v,(k+1)%3)}','autre'),('{fr2Imperatif(v,(k+2)%3)}','autre2'),('{v}','infinitif')],['Retrouve la personne visée par l’ordre ou le conseil.','La forme attendue est {answer}.'],vars={'v':{'pick':['parler','finir','être','avoir']},'k':{'int':[0,2]}},misc=[('autre','Cette forme s’adresse à une autre personne grammaticale.'),('autre2','La personne ne correspond pas à la consigne.'),('infinitif','L’infinitif peut figurer sur certaines consignes, mais on demande ici l’impératif conjugué.')],sources=SRC)
unit(29,'L’impératif présent','former une consigne ou un conseil à la personne demandée sans ajouter de sujet exprimé',
 'les consignes, les pronoms conjoints et le présent','l’accord du verbe et la lettre personnelle',
 'L’impératif peut exprimer un ordre, un conseil ou une invitation. Il comporte les personnes correspondant à tu, nous et vous, sans pronom sujet exprimé. Les verbes en -er perdent normalement le -s à la personne de tu ; devant en ou y directement liés au verbe, un -s euphonique peut apparaître. Être et avoir ont des formes particulières. À l’affirmatif, les pronoms compléments suivent généralement le verbe avec des traits d’union ; au négatif, ils le précèdent.',
 'Modèle original : {fr2Imperatif("parler",0)} calmement. {fr2Imperatif("finir",2)} la phrase. {fr2Imperatif("être",0)} attentif. Compare une invitation adressée au groupe et une demande à un interlocuteur. Ne me le dis pas place les pronoms avant le verbe ; dis-le-moi les place après. Ces modèles écrits préparent une pratique orale avec un partenaire.',
 'Identifie le destinataire et la personne grammaticale. Choisis l’impératif, puis vérifie l’orthographe et la place des compléments. Ne confonds pas une forme impérative avec une phrase déclarative comportant tu. Écris enfin une consigne originale adaptée à une situation de classe.',[
 F('destinataire','la personne ou le groupe auquel s’adresse la consigne','{fr2Imperatif("finir",2)} convient à la personne de vous.','Toutes les consignes s’adressent grammaticalement à tu.','La personne dépend du destinataire visé.'),
 F('sujet non exprimé','l’absence de pronom sujet devant l’impératif','{fr2Imperatif("parler",0)} calmement forme une consigne sans tu.','Toute forme impérative doit commencer par un pronom sujet.','Le sujet n’est pas exprimé dans le modèle impératif.'),
 F('forme particulière','un impératif à apprendre pour certains verbes','{fr2Imperatif("être",0)} est l’impératif de être à la personne visée.','Être suit toujours exactement le modèle de parler.','Certaines formes sont irrégulières.'),
 F('place des compléments','un ordre dépendant notamment de l’affirmation ou de la négation','Dis-le-moi se compare à ne me le dis pas.','L’ordre des pronoms ne change jamais selon la construction.','Il faut examiner la forme affirmative ou négative et les pronoms employés.')],imper,[4,5,19,22])

unit(3,'Les pronoms compléments : lui, leur, y, en','remplacer un complément par le pronom adapté à la construction et au sens',
 'les sujets, les compléments et les groupes nominaux de la classe précédente','l’emploi conjoint des pronoms COD et COI',
 'Un pronom complément reprend une information identifiable. Dans les modèles de parler à une personne, lui reprend un destinataire singulier et leur un destinataire pluriel, sans marque de genre. Y peut reprendre un lieu ou certains compléments en à ; en peut reprendre un complément en de ou une quantité. Le choix dépend du verbe : on ne transforme pas mécaniquement tout à en lui. Avec penser à une personne, on garde par exemple une forme tonique comme à elle. Leur pronom reste invariable.',
 'Modèles originaux : Bih {fr2Present("parler",3)} à sa tante → Bih lui {fr2Present("parler",3)}. Elle {fr2Present("parler",3)} aux voisins → elle leur {fr2Present("parler",3)}. Elle {fr2Present("aller",3)} à Buea → elle y {fr2Present("aller",3)}. Elle {fr2Present("parler",3)} du projet → elle en {fr2Present("parler",3)}. La reprise conserve le référent et le sens de la construction.',
 'Souligne le groupe remplacé, repère la préposition et vérifie ce qu’il désigne. Ne remplace pas le sujet à la place du complément. Pour une quantité, conserve l’indication nécessaire : elle en prend une. Écris ensuite un échange original avec un référent clairement annoncé.',[
 F('lui','le pronom reprenant un destinataire singulier dans le modèle de parler à','Elle lui {fr2Present("parler",3)} reprend à sa tante.','Lui désigne obligatoirement un homme.','Le pronom complément lui peut reprendre une personne de genre féminin ou masculin.'),
 F('leur','le pronom reprenant plusieurs destinataires dans ce modèle','Elle leur {fr2Present("parler",3)} reprend aux voisins.','Le pronom complément leur prend toujours un s.','Leur pronom complément est invariable, contrairement à certains déterminants possessifs.'),
 F('y','un pronom reprenant notamment un lieu dans le modèle étudié','Elle y {fr2Present("aller",3)} reprend à Buea.','Y remplace ici le sujet elle.','Il reprend le lieu, sans changer le sujet.'),
 F('en','un pronom reprenant notamment un complément en de ou une quantité','Elle en {fr2Present("parler",3)} reprend du projet.','En impose de supprimer toute quantité utile au sens.','La reprise doit garder les précisions nécessaires à l’énoncé.')],
 choose(3,[('Elle parle à sa tante. Remplace seulement à sa tante.','lui',['leur','y','en'],['Le destinataire est singulier.','Le modèle vise une personne à qui elle parle, non un lieu.','Le complément est en à, non en de.'],'Lui convient à parler à cette personne.'),('Elle parle aux voisins. Remplace seulement aux voisins.','leur',['lui','y','en'],['Les destinataires sont pluriels.','Le groupe désigne les personnes à qui elle parle.','Le complément n’est pas introduit par de.'],'Leur reprend les destinataires pluriels.'),('Elle va à Buea. Remplace le lieu.','y',['lui','leur','en'],['On reprend le lieu, non un destinataire singulier.','Le lieu n’est pas un groupe de destinataires.','En ne reprend pas ici la destination en à.'],'Y reprend le complément de lieu.'),('Elle parle du projet. Remplace du projet.','en',['lui','leur','y'],['Le projet n’est pas la personne à qui elle parle.','Il ne s’agit pas de plusieurs destinataires.','Le complément du verbe est ici en de.'],'En reprend de ce projet.')]))

unit(5,'L’emploi conjoint des pronoms COD et COI','ordonner les pronoms dans les modèles déclaratifs et impératifs sans modifier leurs référents',
 'lui, leur, y et en et l’identification des compléments','l’impératif et la précision des reprises dans un récit',
 'Avant un verbe conjugué, me, te, se, nous et vous précèdent généralement le, la, les ; le, la, les précèdent lui et leur dans les combinaisons étudiées. Y et en occupent des places particulières. Toutes les combinaisons ne sont pas possibles. À l’impératif affirmatif, le verbe précède les pronoms avec des traits d’union : envoie-le-moi. Au négatif, les pronoms reviennent avant le verbe : ne me l’envoie pas. Me et te peuvent devenir moi et toi ou s’élider selon leur place et le contexte.',
 'Modèles originaux : Je le lui {fr2Present("envoyer",0)} reprend le message et à Bih. Elle me l’{fr2Present("envoyer",3)} reprend un objet déjà identifié. À l’affirmatif : {fr2Imperatif("envoyer",0)}-le-moi. Au négatif : ne me l’{fr2Imperatif("envoyer",0)} pas. Il faut analyser les deux compléments avant de déplacer les mots.',
 'Identifie ce qui est envoyé et à qui. Choisis les pronoms, vérifie la construction affirmative ou négative, puis l’ordre, l’élision et les traits d’union. Une suite mémorisée ne remplace pas l’analyse du sens. Réemploie le modèle dans un court dialogue original.',[
 F('COD repris','l’objet directement rattaché au verbe dans les modèles','Le message devient le dans je le lui envoie.','Lui remplace nécessairement le message envoyé.','Le reprend ici l’objet ; lui reprend le destinataire.'),
 F('COI repris','le destinataire introduit par à dans les modèles','À Bih devient lui dans je le lui envoie.','Le COD et le destinataire sont toujours la même information.','Ils remplissent des rôles distincts dans le modèle.'),
 F('ordre avant le verbe','la succession des pronoms dans une construction déclarative étudiée','Elle me l’envoie place me avant le pronom objet élidé.','Elle le me envoie est le modèle écrit attendu.','Me précède le pronom COD dans cette combinaison.'),
 F('impératif affirmatif','la construction plaçant les pronoms après le verbe avec des traits d’union','Envoie-le-moi se distingue de ne me l’envoie pas.','Une phrase négative conserve forcément envoie-le-moi pas.','La négation change la position et certaines formes des pronoms.')],
 choose(5,[('Remplace le message et à Bih dans Je transmets le message à Bih, avec envoyer au présent.','Je le lui {fr2Present("envoyer",0)}.',['Je lui le {fr2Present("envoyer",0)}.','Je le leur {fr2Present("envoyer",0)}.','Je lui {fr2Present("envoyer",0)}.'],['Le pronom COD précède lui dans ce modèle.','Le destinataire annoncé est singulier.','Le message demandé n’est pas repris.'],'Les deux reprises restent explicites.'),('Remplace la lettre et aux voisines dans Elle envoie la lettre aux voisines.','Elle la leur {fr2Present("envoyer",3)}.',['Elle leur la {fr2Present("envoyer",3)}.','Elle le leur {fr2Present("envoyer",3)}.','Elle la lui {fr2Present("envoyer",3)}.'],['La précède leur.','Lettre exige la dans cette reprise.','Les destinataires sont pluriels.'],'Conserve genre de l’objet et nombre des destinataires.'),('Donne un ordre affirmatif à tu : envoyer le message à moi.','{fr2Imperatif("envoyer",0)}-le-moi.',['{fr2Imperatif("envoyer",0)}-moi-le.','Me le {fr2Imperatif("envoyer",0)}.','{fr2Imperatif("envoyer",0)} le moi.'],['Le COD précède moi dans ce modèle.','À l’affirmatif les compléments suivent le verbe.','Les traits d’union sont nécessaires.'],'Le modèle écrit est verbe-COD-moi.'),('Donne l’ordre négatif correspondant à envoie-le-moi.','Ne me l’{fr2Imperatif("envoyer",0)} pas.',['Ne {fr2Imperatif("envoyer",0)}-le-moi pas.','Ne moi le {fr2Imperatif("envoyer",0)} pas.','Ne le me {fr2Imperatif("envoyer",0)} pas.'],['Au négatif les pronoms précèdent le verbe.','On emploie me avant le verbe.','Me précède le COD, qui s’élide devant envoie.'],'La négation exige ici ne me l’envoie pas.')]),[3])

unit(13,'La phrase complexe introduite par que','repérer une subordonnée complétive et distinguer que conjonction de que pronom relatif',
 'les phrases simples et les verbes de parole ou de pensée','le subjonctif et les pronoms relatifs composés',
 'Une phrase complexe comporte plusieurs propositions. La conjonction de subordination que peut introduire une proposition complétant un verbe : Bih dit que la réunion commence. La proposition introduite dépend de la principale. Dans cette construction, que n’occupe pas lui-même la fonction de COD à l’intérieur de la subordonnée. Compare le livre que Bih lit : ici que est un pronom relatif reprenant livre et jouant un rôle dans sa proposition. La présence du même mot ne suffit donc pas à décider de l’analyse ou du mode.',
 'Modèle original : Ayuk affirme que le groupe est prêt. Ayuk affirme constitue la principale ; que le groupe est prêt complète le verbe. Dans le livre que Bih lit, que reprend un nom antécédent. Enfin, il faut que le groupe soit prêt n’emploie pas le même mode que un constat : c’est la construction complète qui guide le choix.',
 'Repère les verbes conjugués, les limites des propositions et ce que la subordonnée complète. Cherche si que reprend un antécédent et occupe une fonction interne. Garde le sens lorsque tu réunis des phrases ; ne suppose pas que chaque que exige le subjonctif.',[
 F('principale','la proposition dont dépend la subordonnée dans le modèle','Dans Bih dit que le club ouvre, Bih dit porte le verbe principal.','Le dernier groupe de mots est toujours la principale.','La dépendance grammaticale, non la seule position, décide.'),
 F('complétive','une proposition complétant notamment un verbe dans le modèle étudié','Que la salle est prête complète elle affirme.','Une complétive doit toujours être une proposition indépendante sans lien.','Elle dépend ici du verbe qu’elle complète.'),
 F('que conjonction','un mot de subordination ne reprenant pas un nom dans le modèle','Je pense que la salle est ouverte introduit le contenu pensé.','Que conjonction reprend toujours le nom salle placé avant lui.','Il introduit ici une proposition, sans antécédent nominal repris.'),
 F('que relatif','un pronom reprenant un antécédent et jouant un rôle dans sa proposition','Le livre que Bih lit contient que reprenant livre.','Que a forcément la même nature dans toutes les phrases.','Compare reprise d’un antécédent et simple subordination.')],
 choose(13,[('Quelle suite complète le contenu de Bih affirme dans Bih affirme que la salle est prête ?','que la salle est prête',['Bih seule','la seule salle','affirme sans aucun complément'],['Le sujet seul ne fournit pas le contenu affirmé.','Cela ne reprend pas la proposition complète.','Le verbe isolé omet le contenu demandé.'],'La proposition introduite par que exprime ce qui est affirmé.'),('Dans le livre que Bih lit, que reprend quel antécédent ?','le livre',['Bih','aucun nom : c’est nécessairement une conjonction','la phrase entière sans distinction'],['Bih est le sujet de lit.','Ici que reprend bien un groupe nominal.','Le référent demandé est le nom repris.'],'Que est ici relatif.'),('Quel énoncé garde une complétive après un verbe de pensée ?','Je pense que le groupe est prêt.',['Le groupe, dont je parle.','Le livre que Bih lit.','Le groupe et la salle.'],['Ce fragment ne fournit pas le modèle demandé.','Il s’agit d’une relative rattachée au livre.','Une coordination de noms ne constitue pas cette complétive.'],'Le contenu pensé est une proposition dépendante.'),('Pourquoi le mode ne dépend-il pas seulement de que ?','La construction et le sens, par exemple constat ou nécessité, comptent.',['Tous les que sont des verbes.','Toute phrase avec que est sans verbe.','Chaque que oblige à mettre le même temps.'],['Que n’est pas le verbe de la proposition.','Les propositions contiennent des verbes conjugués.','Les constructions n’imposent pas toutes le même mode ou temps.'],'Il faut analyser l’expression qui commande la subordonnée.')]),[3,10])

meteo=B.mcq('fr4-18-forme',2,'Complète l’emploi météorologique impersonnel au présent : « {v} ». Choisis le groupe complet.','il {fr2Present(v,2)}',
 [('nous {fr2Present(v,4)}','pluriel'),('je {fr2Present(v,0)}','personne'),('il {v}','infinitif')],['Dans l’emploi météorologique demandé, il ne renvoie pas à une personne.','Le groupe est {answer}.'],vars={'v':{'pick':['neiger','venter','tonner','geler']}},misc=[('pluriel','Le modèle météorologique impersonnel demandé ne prend pas nous comme sujet.'),('personne','Je ne correspond pas au sujet impersonnel demandé.'),('infinitif','Le verbe doit être conjugué au présent après il.')],sources=SRC)
unit(18,'Les verbes impersonnels','reconnaître un il impersonnel et former les modèles météorologiques réguliers étudiés',
 'les sujets et les formes personnelles de l’indicatif','il faut que et les constructions de nécessité',
 'Dans un emploi impersonnel, il ne renvoie pas à un être ou à un objet identifiable. Les expressions météorologiques telles que il pleut ou il neige fournissent des modèles courants. Falloir exprime notamment une nécessité : il faut attendre ou il faut que le groupe soit prêt. Il faut distinguer ces emplois d’un il personnel reprenant un garçon ou un objet masculin. Certains verbes peuvent aussi avoir des emplois figurés ou personnels ; on ne généralise pas le modèle à tous les contextes.',
 'Modèles de reconnaissance : il pleut décrit un phénomène ; il faut indique une nécessité. Pour les verbes réguliers étudiés : il {fr2Present("neiger",2)}, il {fr2Present("venter",2)}, il {fr2Present("tonner",2)} et il {fr2Present("geler",2)}. Ce sont des exemples de langue, pas une prévision pour Buea. Dans Ayuk arrive ; il sourit, le second il reprend une personne et n’a pas le même fonctionnement.',
 'Demande si il a un référent identifiable. Examine ensuite la construction, plutôt que d’inventer un nom caché pour chaque sujet. Après il faut, distingue l’infinitif sans sujet propre de la proposition en que. Réemploie une expression dans un exemple fictif, sans prétendre décrire la météo actuelle.',[
 F('il impersonnel','un sujet grammatical ne renvoyant pas ici à une personne ou un objet précis','Dans il pleut, il ne nomme pas une personne qui ferait la pluie.','Chaque il doit reprendre un homme mentionné auparavant.','Certains emplois de il n’ont pas ce référent personnel.'),
 F('phénomène météorologique','un événement de temps exprimé par le modèle impersonnel','Il {fr2Present("neiger",2)} est un exemple de langue.','Un exemple grammatical prouve qu’il neige actuellement à Buea.','Le modèle de conjugaison ne constitue pas une observation météorologique.'),
 F('nécessité','ce que falloir peut présenter comme requis','Il faut attendre présente une nécessité dans la situation.','Il faut décrit toujours uniquement de la pluie.','Le sens de nécessité diffère de l’exemple météorologique.'),
 F('il personnel','un pronom renvoyant à un référent identifiable','Ayuk arrive ; il sourit reprend Ayuk.','Le il de il sourit est toujours le même emploi que dans il pleut.','Le référent identifiable distingue ici les emplois.')],meteo,[15])

unit(20,'Les pronoms relatifs composés','choisir lequel et ses formes contractées selon l’antécédent et la préposition',
 'les compléments et la distinction entre conjonction et pronom relatif','la précision des liens dans les descriptions et les lettres',
 'Lequel varie selon le genre et le nombre de son antécédent : lequel, laquelle, lesquels, lesquelles. Après à et de, des formes se contractent : auquel, auxquels, auxquelles ; duquel, desquels, desquelles. Au féminin singulier, on garde à laquelle et de laquelle. D’autres prépositions peuvent précéder la forme simple : avec lequel, sur laquelle. Le choix exige de retrouver le nom repris et la préposition commandée par la relation. Pour une personne, qui après préposition peut aussi convenir selon le contexte.',
 'Modèles originaux : le livre avec lequel je travaille ; la table sur laquelle le cahier repose ; les projets auxquels elle réfléchit ; les salles près desquelles le groupe attend. Le livre et la table imposent des genres différents. Réfléchir à conserve la relation en à ; près de garde de dans sa construction.',
 'Repère l’antécédent complet, son genre et son nombre, puis la préposition. Ne choisis pas une forme seulement parce qu’elle est proche du verbe. Écris une description originale avec une forme composée et vérifie que le lien obtenu garde le sens.',[
 F('antécédent','le nom ou groupe repris par le relatif','Dans le livre avec lequel, livre commande le masculin singulier.','Le relatif choisit son genre d’après un nom au hasard.','L’accord se fait avec l’antécédent repris.'),
 F('accord du relatif','la variation en genre et nombre de lequel','La table sur laquelle emploie le féminin singulier.','Lequel reste toujours masculin singulier.','Lequel appartient à une série variable.'),
 F('contraction en à','la combinaison de à avec certaines formes de lequel','Les projets auxquels elle réfléchit conserve la préposition à.','À lequel reste toujours écrit en deux mots.','Les formes auxquelles la contraction s’applique s’écrivent en un mot.'),
 F('contraction en de','la combinaison de de avec certaines formes de lequel','Les salles près desquelles reprend de et le féminin pluriel.','Duquel signifie automatiquement à laquelle.','La préposition et l’accord ne doivent pas être confondus.')],
 choose(20,[('Le livre avec ___ je travaille.','lequel',['laquelle','lesquels','duquel'],['Livre est masculin.','Livre est singulier.','Avec n’impose pas une forme contractée en de.'],'Accorde avec livre après avec.'),('La table sur ___ repose le cahier.','laquelle',['lequel','lesquelles','auquel'],['Table est féminin.','Table est singulier.','Sur ne se remplace pas par à.'],'Accorde avec table après sur.'),('Les projets ___ elle réfléchit.','auxquels',['lesquels','auquel','auxquelles'],['Réfléchir demande ici à.','Projets est pluriel.','Projets est masculin.'],'À plus lesquels donne auxquels.'),('Les salles près ___ le groupe attend.','desquelles',['duquel','auxquelles','lesquelles'],['Salles est féminin pluriel.','Près demande ici de, non à.','Il manque la relation en de.'],'Près de plus lesquelles donne près desquelles.')]),[13,18])

degrees=B.mcq('fr4-23-accorder',2,'Dans le modèle « plus ___ que », accorde « {a} » pour un nom {fr2GenderNumber(g,pl)}.','{fr2Adj(a,g,pl)}',
 [('{fr2Adj(a,fr2OtherGender(g),pl)}','genre'),('{fr2Adj(a,g,!pl)}','nombre'),('{fr2Adj(a,fr2OtherGender(g),!pl)}','deux')],['Plus marque ici le degré, mais l’adjectif garde son accord.','La forme est {answer}.'],vars={'a':{'pick':['grand','petit','beau','nouveau']},'g':{'pick':['m','f']},'pl':{'pick':[True,False]}},misc=[('genre','Cette forme change le genre du nom qualifié.'),('nombre','Cette forme change le nombre du nom qualifié.'),('deux','Cette forme change à la fois le genre et le nombre.')],sources=SRC)
unit(23,'Comparatif et superlatif de l’adjectif','exprimer une comparaison ou un classement en conservant l’accord et le sens',
 'les adjectifs qualificatifs et leur accord','les descriptions nuancées et l’argumentation',
 'Le comparatif met en relation des éléments : plus grand que, aussi grand que ou moins grand que. Le superlatif relatif situe un élément dans un ensemble : le plus grand de la classe. L’adjectif conserve son accord avec le nom ; plus ne remplace pas une marque de genre ou de nombre. Certains adjectifs ont des formes particulières, comme meilleur pour bon. Distingue bon, adjectif, de bien, souvent adverbe. Un superlatif exige un ensemble de référence clair plutôt qu’une supériorité affirmée sans contexte.',
 'Modèle original : Cette cour est plus {fr2Adj("grand","f",false)} que l’autre. Ces salles sont aussi {fr2Adj("propre","f",true)} que le modèle. Dans le groupe décrit, la salle choisie est la plus grande. La comparaison porte sur une caractéristique précisée, pas sur la valeur personnelle des élèves.',
 'Détermine les éléments comparés et la qualité choisie. Sélectionne supériorité, égalité ou infériorité, puis accorde l’adjectif. Pour un classement, nomme l’ensemble. Écris une comparaison originale d’objets ou de lieux en évitant les jugements sur le corps ou la dignité des personnes.',[
 F('supériorité','une comparaison exprimée notamment par plus et que','Une cour est plus grande qu’une autre dans le modèle.','Plus supprime toujours l’accord de l’adjectif.','Le degré et l’accord remplissent des fonctions différentes.'),
 F('égalité','une comparaison exprimée notamment par aussi et que','Les salles sont aussi propres que le modèle.','Aussi signifie nécessairement moins.','Aussi marque ici une égalité de la qualité comparée.'),
 F('infériorité','une comparaison exprimée notamment par moins et que','Un chemin est moins large que l’autre.','Moins large signifie toujours plus large.','La relation de comparaison doit être conservée.'),
 F('superlatif relatif','un degré maximal ou minimal rapporté à un ensemble','La plus grande salle du groupe est distinguée.','Tout superlatif relatif se comprend sans aucun ensemble de référence.','Le classement dépend de l’ensemble comparé.')],degrees,[20,22])

unit(28,'Fonctions de l’adjectif qualificatif','distinguer l’épithète liée, l’attribut et l’adjectif détaché en identifiant le nom qualifié',
 'l’accord adjectival, les comparatifs et la phrase complexe','l’impératif et la précision des descriptions écrites',
 'L’adjectif épithète liée accompagne directement le nom dans le groupe nominal : une cour calme. L’attribut du sujet passe par un verbe attributif : la cour est calme. Un adjectif détaché, souvent appelé épithète détachée ou apposition adjectivale dans les cours, est séparé du groupe par une ponctuation : Calme, Bih écoute. La terminologie doit rester cohérente avec celle du professeur. Ne confonds pas cet adjectif avec un adverbe : calmement modifie ici le verbe, sans qualifier un nom par accord.',
 'Modèle original : Une petite cour accueille le groupe. La cour est calme. Fatiguée, Bih s’assoit. Elle parle calmement. Petite accompagne cour ; calme est relié au sujet par est ; fatiguée se rapporte à Bih malgré son détachement ; calmement caractérise la manière de parler. La seule proximité des mots ne suffit pas à attribuer une fonction.',
 'Retrouve le mot caractérisé et le lien syntaxique. Vérifie le verbe attributif ou le détachement. Examine la ponctuation et l’accord, sans supposer qu’un adjectif placé avant le nom change de classe. Réécris une description originale en variant la fonction d’un même adjectif.',[
 F('épithète liée','un adjectif directement intégré au groupe nominal','Dans une cour calme, calme accompagne cour.','Une épithète liée exige toujours un verbe être entre le nom et l’adjectif.','Elle appartient directement au groupe nominal.'),
 F('attribut du sujet','un adjectif relié au sujet par un verbe attributif','Dans la cour est calme, calme qualifie le sujet.','Tout mot après être est nécessairement un COD.','Dans ce modèle, le verbe relie une propriété au sujet.'),
 F('adjectif détaché','un adjectif qualifiant un nom ou pronom tout en étant séparé par la ponctuation','Fatiguée, Bih s’assoit contient un adjectif détaché rapporté à Bih.','Un adjectif détaché ne peut jamais avoir de lien d’accord.','Le détachement ne supprime pas le nom ou pronom qualifié.'),
 F('adverbe','un mot modifiant notamment la manière de l’action dans le modèle','Dans elle parle calmement, calmement porte sur parle.','Calmement doit prendre le féminin pluriel du nom cour.','Cet adverbe n’est pas l’adjectif qualifiant cour.')],
 choose(28,[('Analyse calme dans une cour calme.','épithète liée',['attribut du sujet','adjectif détaché','adverbe'],['Aucun verbe attributif ne relie ici l’adjectif.','L’adjectif est intégré au groupe sans détachement.','Calme qualifie le nom.'],'Il accompagne directement cour.'),('Analyse calme dans la cour est calme.','attribut du sujet',['épithète liée','adjectif détaché','adverbe'],['L’adjectif passe ici par est.','Il n’est pas détaché par une virgule.','Il qualifie le sujet, non la manière d’une action.'],'Est relie la qualité au sujet.'),('Analyse fatiguée dans Fatiguée, Bih s’assoit.','adjectif détaché',['épithète liée','attribut du sujet','adverbe'],['La virgule marque le détachement.','Aucun verbe attributif ne porte la relation.','Fatiguée qualifie Bih et s’accorde.'],'La relation adjectivale demeure malgré la séparation.'),('Analyse calmement dans Elle parle calmement.','adverbe',['épithète liée','attribut du sujet','adjectif détaché'],['Le mot ne qualifie pas un nom dans un groupe.','Il n’est pas lié au sujet par un verbe attributif.','Ce n’est pas un adjectif séparé qualifiant elle.'],'Il exprime ici la manière de parler.')]),[13,23])

agreement=B.mcq('fr4-30-accord',2,'Au présent, complète : « {S.text} ___ ». Verbe : {v}. Repère le sujet complet.','{fr2Present(v,S.p)}',
 [('{fr2Present(v,S.p==2 ? 6 : 2)}','nombre'),('{fr2Present(v,4)}','nous'),('{fr2Present(v,5)}','vous')],['Le sujet complet est {S.text}.','Le noyau ou la coordination impose ici {answer}.'],vars={'S':{'pick':[{'text':'Le groupe d’élèves','p':2},{'text':'Les élèves du groupe','p':6},{'text':'Bih et Ayuk','p':6},{'text':'Le frère des voisines','p':2}]},'v':{'pick':['arriver','finir','travailler','choisir']}},misc=[('nombre','Tu as accordé avec un nombre différent de celui du sujet grammatical.'),('nous','Aucun nous n’est le sujet de la phrase donnée.'),('vous','Le sujet donné ne correspond pas à vous.')],sources=SRC)
unit(30,'L’accord du sujet et du verbe','retrouver le sujet grammatical malgré un complément voisin et accorder le présent',
 'les sujets, les pronoms et les formes verbales étudiées','la relecture d’une lettre et des productions autonomes',
 'Le verbe s’accorde en personne et en nombre avec son sujet grammatical. Un complément placé près du verbe ne devient pas automatiquement le sujet. Dans le groupe d’élèves arrive, le noyau groupe est singulier ; dans les élèves du groupe arrivent, le noyau élèves est pluriel. Des sujets coordonnés par et appellent normalement le pluriel dans les modèles étudiés. Certaines constructions collectives ou particulières exigent une analyse plus fine ; cette leçon utilise des cas explicites sans étendre mécaniquement une règle à toute expression de quantité.',
 'Modèle original : Le groupe d’élèves {fr2Present("arriver",2)}. Les élèves du groupe {fr2Present("arriver",6)}. Bih et Ayuk {fr2Present("travailler",6)}. Le frère des voisines {fr2Present("finir",2)}. Trouve le noyau ou la coordination, puis vérifie la forme ; le mot le plus proche n’est pas une règle d’accord.',
 'Encadre le sujet complet, distingue son noyau de ses compléments et détermine personne et nombre. Relis ensuite la terminaison. Ne transforme pas une phrase à la seule vue d’un nom pluriel voisin. Vérifie ces accords dans une phrase originale puis dans ta lettre.',[
 F('sujet grammatical','le groupe commandant l’accord du verbe','Le groupe d’élèves est le sujet complet du premier modèle.','Le sujet est toujours le dernier nom rencontré.','Il faut identifier la fonction, pas seulement la proximité.'),
 F('noyau du groupe','le mot central déterminant ici le nombre du groupe sujet','Groupe est le noyau de le groupe d’élèves.','Le complément d’élèves transforme automatiquement groupe en pluriel.','Dans ce modèle, le noyau singulier commande l’accord.'),
 F('coordination','l’association de sujets appelant ici un accord pluriel','Bih et Ayuk {fr2Present("travailler",6)}.','Deux sujets distincts liés par et imposent ici le singulier.','Le modèle coordonne les personnes et appelle le pluriel.'),
 F('complément du nom','un groupe précisant le nom sans être à lui seul le sujet','Des voisines complète frère dans le frère des voisines.','Un complément nominal remplace toujours le sujet de la phrase.','Sa fonction de précision ne lui donne pas automatiquement le rôle de sujet.')],agreement,[10,15,28,29])

def vocab(n,title,goal,back,onward,note,model,facts,gaps,prereq=()):
    bank=[]
    for text,term in gaps:
        target=next(f for f in facts if f['term']==term)
        other=[f for f in facts if f['term']!=term][:3]
        bank.append(item(text+'\nQuel mot ou groupe de la leçon convient ?',term,[(f['term'],'Ce mot désigne '+f['meaning']+'. La phrase demande plutôt '+target['meaning']+'.') for f in other],target['why']))
    unit(n,title,goal,back,onward,note,model,'Lis la phrase entière, repère la relation de sens et choisis un mot adapté au contexte. Une proximité de thème ne rend pas tous les mots interchangeables. Réemploie ensuite un mot dans une phrase originale et vérifie ce que tu veux dire.',facts,qa(n,'contexte',2,bank),prereq)

vocab(1,'La vie familiale et sociale : vocabulaire','choisir un vocabulaire précis pour décrire une situation familiale ou sociale fictive sans jugement sur les personnes',
 'les descriptions et les relations sociales de la classe précédente','la lecture d’un récit et les reprises pronominales',
 'Un vocabulaire précis distingue des réalités différentes. Le mariage désigne une union reconnue dans le cadre évoqué ; le divorce en désigne la dissolution légale, sans que ces mots expliquent les procédures locales. Un litige est un désaccord pouvant demander une résolution. La violence ne se limite pas à un désaccord exprimé calmement. Le décrochage scolaire concerne l’interruption ou l’éloignement du parcours scolaire. Un orphelinat est une institution d’accueil pour enfants orphelins. Les situations réelles et leurs causes sont variées : on ne déduit ni la valeur d’une personne ni toute son histoire d’une étiquette.',
 'Dialogue original : Dans une histoire inventée à Bamenda, un club prépare une collecte de livres pour une institution d’accueil. Bih demande quel public est concerné avant de rédiger l’annonce. Ayuk refuse d’attribuer la même histoire à tous les enfants. Le vocabulaire sert à décrire avec précision, pas à demander aux élèves de révéler leur propre vie familiale.',[
 F('mariage','une union reconnue dans le cadre évoqué','Le récit mentionne une union sans expliquer une procédure juridique.','Le mot mariage fournit à lui seul toutes les règles applicables dans chaque pays.','Le vocabulaire ne remplace pas l’étude des règles locales.'),
 F('divorce','la dissolution légale d’un mariage','Un personnage fictif évoque la fin légale de son mariage.','Divorce signifie seulement une discussion sans rapport avec une union.','Le sens renvoie à la dissolution du mariage, pas à tout désaccord.'),
 F('litige','un désaccord nécessitant une résolution entre parties','Des personnages ne s’accordent pas sur l’usage d’un bien.','Tout litige signifie que toutes les personnes sont identiques et coupables.','Nommer un désaccord ne permet pas d’attribuer une responsabilité sans faits.'),
 F('violence','une atteinte ou une contrainte qui ne se confond pas avec tout désaccord calme','Le récit distingue une menace d’une discussion respectueuse.','Une menace est simplement un synonyme de discussion calme.','La précision évite de banaliser une atteinte ou de confondre des situations.'),
 F('décrochage scolaire','une rupture ou un éloignement du parcours scolaire','Le récit s’interroge sur une interruption de scolarité.','Une interruption de scolarité prouve que la personne n’a aucune valeur.','Les causes sont multiples et n’autorisent pas un jugement sur la personne.'),
 F('orphelinat','une institution accueillant des enfants orphelins','Le club écrit une annonce destinée à une institution d’accueil.','Le nom d’une institution raconte toute l’histoire de chaque enfant.','Une catégorie générale ne décrit pas chaque parcours individuel.')],
 [('Le récit désigne la dissolution légale d’une union : le ___.','divorce'),('Des parties cherchent une solution à leur désaccord : un ___.','litige'),('L’annonce concerne une institution d’accueil pour enfants orphelins : un ___.','orphelinat'),('Le texte examine une rupture du parcours scolaire : le ___.','décrochage scolaire')])

unit(8,'L’affixation','repérer un préfixe ou un suffixe et expliquer le changement de sens ou de catégorie dans les modèles',
 'le vocabulaire en contexte et l’orthographe des mots','les familles de mots et l’enrichissement du récit',
 'L’affixation forme des mots en ajoutant un préfixe ou un suffixe à une base. Un préfixe se place avant la base ; un suffixe après. Re- peut exprimer une répétition dans revoir ; -eur peut désigner une personne dans chanteur. Le sens dépend du mot complet : une suite de lettres ressemblante n’est pas automatiquement un affixe. Un suffixe peut changer la catégorie grammaticale, mais toutes les combinaisons imaginables ne produisent pas un mot employé. Vérifie le sens et l’existence du mot.',
 'Modèles originaux : revoir associe re- et voir ; chanteur est lié à chanter ; rapidement est un adverbe construit sur rapide. La famille conserve un lien de sens, parfois avec un ajustement de la base. À Buea, Bih relit une annonce : relire signifie ici lire de nouveau, sans changer le contenu du message par hasard.',
 'Sépare les éléments seulement si le sens et la formation le permettent. Explique ce que l’ajout apporte, puis vérifie la catégorie obtenue. Réemploie un mot dérivé dans une phrase originale sans fabriquer une forme non attestée.',[
 F('préfixe','un élément ajouté avant une base','Re- précède voir dans le modèle revoir.','Un préfixe se place obligatoirement après la base.','Sa position se situe avant la base.'),
 F('suffixe','un élément ajouté après une base','Le suffixe -eur contribue à former chanteur.','Un suffixe est toujours un mot entièrement indépendant placé avant.','Il s’ajoute après la base dans le modèle.'),
 F('base','l’élément sur lequel s’effectue l’ajout étudié','Voir sert de base au modèle revoir.','La base est forcément le dernier signe de ponctuation.','La base appartient à la formation du mot, non à la ponctuation.'),
 F('dérivation','la formation d’un mot à partir d’une base avec un lien de sens','Rapide et rapidement sont liés par une formation dérivée.','Toute suite de lettres ajoutée crée nécessairement un mot correct.','L’existence et le sens du mot doivent être vérifiés.')],
 choose(8,[('Quel élément est préfixé dans revoir ?','re-',['-eur','voir','-ment'],['-eur est un suffixe comme dans chanteur ; il ne figure pas dans revoir.','Voir est la base, pas l’élément ajouté avant elle.','-ment est un suffixe comme dans rapidement ; il ne figure pas dans revoir.'],'Re- précède voir.'),('Quel mot est lié à chanter par suffixation ?','chanteur',['revoir','table','demain'],['Ce mot relève d’une autre formation.','Le sens et la base ne correspondent pas.','Le mot ne se forme pas sur chanter.'],'Le lien de forme et de sens est conservé.'),('Quelle catégorie convient à rapidement dans elle avance rapidement ?','adverbe',['nom de personne','pronom sujet','préposition de lieu'],['Il ne nomme pas une personne.','Elle est le sujet, non rapidement.','Il exprime la manière, pas cette relation de lieu.'],'Le suffixe contribue ici à une forme adverbiale.'),('Pourquoi ne suffit-il pas de découper des lettres identiques ?','Il faut un lien de formation et de sens.',['Tous les mots ont le même préfixe.','Chaque lettre est un suffixe.','Le sens n’intervient jamais.'],['Les formations varient.','Un suffixe n’est pas n’importe quelle lettre.','Le sens fait partie de l’analyse.'],'La ressemblance visuelle seule peut tromper.')]),[1,7])

unit(14,'Les familles de mots','regrouper des mots selon un lien de formation et de sens et distinguer une famille d’un simple thème',
 'l’affixation et le vocabulaire en contexte','l’enrichissement de la narration et des thèmes environnementaux',
 'Une famille de mots réunit des mots liés par leur formation et leur sens, souvent autour d’un radical commun. Chanter, chant et chanteur appartiennent à une même famille. Un champ lexical rassemble des mots d’un même domaine sans exiger une base commune : médecin, hôpital et consultation peuvent relever de la santé sans former une seule famille morphologique. Une ressemblance sonore n’établit pas davantage une parenté. Certains radicaux changent de forme ; le dictionnaire aide à vérifier les cas moins transparents.',
 'Modèles originaux : dent, dentiste, dentaire ; lait, laitier, laiterie ; terre, terrain, terrestre. Dans une description de marché, lait et vendeur partagent un contexte possible mais pas nécessairement la même famille. Il faut conserver la distinction entre un thème de récit et une relation de formation des mots.',
 'Cherche une base et un lien de sens, puis teste le mot complet dans le contexte. N’exclus pas automatiquement une variation du radical, mais ne rapproche pas des homophones sans preuve. Écris une phrase originale avec des mots d’une famille en évitant les répétitions inutiles.',[
 F('famille morphologique','des mots liés par leur formation et leur sens','Dent, dentiste et dentaire sont rapprochés.','Une famille réunit obligatoirement tous les mots d’un même thème.','Le lien de formation distingue famille et simple thème.'),
 F('radical','un élément commun ou apparenté dans les formations étudiées','Chant se retrouve dans chanter et chanteur.','Un radical est le seul accent visible d’un mot.','Il concerne la base lexicale de la formation.'),
 F('champ lexical','un ensemble de mots associés à un même domaine','Médecin, hôpital et consultation renvoient à la santé.','Tous les mots du champ de la santé ont forcément la même base.','Un thème commun n’impose pas une même formation.'),
 F('homophonie','une ressemblance de prononciation sans parenté morphologique automatique','Mer et mère ne deviennent pas une famille par le seul son.','Deux mots de même prononciation ont toujours la même formation.','Le son seul ne prouve pas une parenté de mots.')],
 choose(14,[('Choisis la famille cohérente autour de dent.','dent, dentiste, dentaire',['dent, hôpital, ordonnance','dent, demain, dehors','dent, lait, table'],['C’est un voisinage thématique, pas une seule base.','La formation et le sens ne sont pas communs.','Le regroupement mélange des bases différentes.'],'La parenté dépasse le simple thème.'),('Choisis la famille cohérente autour de lait.','lait, laitier, laiterie',['lait, marché, vendeur','lait, lit, lui','lait, pluie, cour'],['Le contexte commercial ne crée pas une famille morphologique.','La ressemblance graphique ne suffit pas.','Ces mots n’ont pas la base demandée.'],'Les trois mots sont liés par forme et sens.'),('Choisis la famille cohérente autour de chant.','chant, chanter, chanteur',['chant, danse, spectacle','chant, champ, chambre','chant, livre, pluie'],['Ces mots peuvent partager un thème artistique sans la même base.','La proximité visuelle ou sonore ne suffit pas.','Les bases ne correspondent pas.'],'La formation relie ces mots.'),('Médecin, hôpital et consultation forment surtout ici quoi ?','un champ lexical de la santé',['une seule conjugaison','trois formes d’un seul pronom','une famille fondée sur un radical unique'],['Ce sont des mots lexicaux, non une série de formes verbales.','Ce ne sont pas trois formes pronominales.','Le thème commun ne fournit pas un radical unique.'],'Le critère est ici le domaine de sens.')]),[8,13])

vocab(17,'La protection de l’environnement : vocabulaire','distinguer réduction, réemploi, tri, recyclage et pollution dans des exemples fictifs',
 'les familles de mots et la précision lexicale','les échanges argumentés et la lecture sur les déchets',
 'Protéger l’environnement demande de nommer précisément les actions. Réduire signifie éviter une part de consommation ou de déchets ; réemployer consiste à utiliser de nouveau un objet approprié ; trier sépare selon des catégories ; recycler transforme une matière par une filière adaptée. Le tri seul ne prouve pas que le recyclage a eu lieu. La pollution concerne une dégradation du milieu par des substances ou d’autres nuisances. Le vocabulaire aide à expliquer une action et ses limites sans prétendre que tout objet a la même filière.',
 'Dialogue original : À Douala, un club propose de limiter les impressions inutiles. Bih suggère de réemployer une boîte propre. Ayuk demande quelles matières la collecte accepte. L’enseignante vérifie les consignes ; les élèves ne manipulent pas de déchets coupants ou inconnus. Le texte prépare un projet sans affirmer qu’il a déjà réussi.',[
 F('réduction','la prévention d’une partie de la consommation ou des déchets','Le club évite des impressions inutiles.','Réduire signifie toujours produire davantage de déchets.','La réduction agit en amont d’une partie des déchets.'),
 F('réemploi','une nouvelle utilisation appropriée d’un objet','Une boîte propre sert de nouveau au rangement.','Tout réemploi exige de transformer industriellement la matière.','L’objet peut rester intact en étant utilisé de nouveau.'),
 F('tri','la séparation selon des catégories prévues','Les matières sont séparées selon les consignes de la collecte.','Trier prouve que toute la matière est déjà recyclée.','Séparation, collecte et transformation sont des étapes différentes.'),
 F('recyclage','la transformation d’une matière par une filière adaptée','La matière collectée entre dans un procédé permettant une nouvelle utilisation.','Chaque déchet a automatiquement une filière accessible.','Le recyclage dépend du matériau, de sa qualité et de la filière.'),
 F('pollution','une dégradation du milieu par des substances ou nuisances','Un rejet dégrade la qualité d’un milieu dans le récit.','Nommer pollution dispense d’examiner sa source et ses effets.','Une explication précise doit identifier ce qui dégrade le milieu.')],
 [('Éviter une impression inutile illustre la ___.','réduction'),('Utiliser de nouveau une boîte propre illustre le ___.','réemploi'),('Séparer selon les catégories de collecte correspond au ___.','tri'),('Transformer une matière dans une filière adaptée correspond au ___.','recyclage')],[8,14,15])

vocab(21,'La santé et les métiers de la santé','employer des noms de professions et d’activités sans confondre vocabulaire et diagnostic',
 'le lexique thématique et les échanges respectueux','le subjonctif, la nutrition et la traduction sur la santé',
 'Le vocabulaire de la santé distingue des professions et des activités. Le médecin évalue et prend en charge des problèmes de santé dans son champ ; l’infirmier ou l’infirmière assure des soins selon ses compétences ; le pharmacien ou la pharmacienne est spécialiste du médicament ; la sage-femme accompagne notamment la santé reproductive, la grossesse et la naissance. Une consultation est une rencontre professionnelle pour évaluer une situation. Les rôles précis dépendent de l’organisation locale ; apprendre ces mots ne permet pas de diagnostiquer ni de prescrire.',
 'Dialogue original : Dans une clinique imaginaire, Bih demande où se trouve l’accueil. Un personnage annonce une consultation, sans donner de dossier médical réel. Le récit nomme plusieurs métiers sans affirmer qu’une profession remplace toutes les autres. Les élèves peuvent employer une situation entièrement fictive et ne doivent pas communiquer leurs données de santé.',[
 F('médecin','un professionnel évaluant et prenant en charge des problèmes de santé dans son champ','Le récit présente un médecin lors d’une consultation.','Connaître le mot médecin donne une qualification médicale.','Un mot de vocabulaire n’est ni une formation clinique ni une autorisation.'),
 F('infirmier ou infirmière','un professionnel assurant des soins selon ses compétences','Une infirmière intervient dans la situation fictive.','Toutes les professions de santé ont exactement les mêmes responsabilités.','Les métiers ont des compétences distinctes et des collaborations.'),
 F('pharmacien ou pharmacienne','un professionnel spécialiste du médicament','Le texte distingue la pharmacie d’un rôle de classe.','Pharmacien signifie vendeur de n’importe quel produit sans compétence spécifique.','Le terme désigne une profession de santé liée au médicament.'),
 F('sage-femme','un professionnel intervenant notamment en santé reproductive grossesse et naissance','Le récit mentionne le suivi de la grossesse par une sage-femme.','Le nom de cette profession décrit uniquement l’âge ou la personnalité.','Il désigne un métier et ses compétences, non un simple trait personnel.'),
 F('consultation','une rencontre professionnelle destinée à examiner une situation de santé','Un personnage prend rendez-vous pour une consultation fictive.','Une consultation est toujours un traitement choisi par un camarade.','Elle ne se confond pas avec une décision clinique prise par un élève.')],
 [('La rencontre professionnelle décrite s’appelle une ___.','consultation'),('Le texte nomme le spécialiste du médicament : le ou la ___.','pharmacien ou pharmacienne'),('Le récit présente le professionnel de soins infirmiers : ___.','infirmier ou infirmière'),('Le texte nomme la profession liée notamment à la grossesse et à la naissance : ___.','sage-femme')],[1,17,20])

vocab(24,'Nutrition et malnutrition : vocabulaire','distinguer alimentation, nutriment, carence et malnutrition dans des phrases informatives',
 'le lexique de la santé et les comparaisons précises','la compréhension et la traduction d’informations générales',
 'L’alimentation concerne ce que l’on mange et boit et les pratiques associées ; un nutriment est une substance utilisée par l’organisme. Une carence est un manque d’un élément nécessaire. La malnutrition peut inclure des insuffisances, des excès ou des déséquilibres : elle ne signifie pas seulement manquer de nourriture. L’hydratation concerne l’apport et l’équilibre en eau. Les besoins varient selon les personnes et les situations. Cette leçon enseigne les mots, sans évaluer le corps, calculer un régime ni attribuer un diagnostic à un élève.',
 'Texte original : Un club lit une affiche générale sur la diversité des aliments. Bih relève le mot nutriment ; Ayuk distingue carence et malnutrition. Ils décident de vérifier le sens avant de résumer. Le récit ne fournit aucun dossier, poids, besoin quotidien ou conseil individualisé. Un exemple de langue ne constitue pas un programme de soins.',[
 F('alimentation','les apports et pratiques liés à ce que l’on mange et boit','Le texte décrit de façon générale la diversité des aliments.','Le mot alimentation signifie nécessairement une prescription médicale personnelle.','Un domaine de vocabulaire ne fournit pas un plan individuel.'),
 F('nutriment','une substance utilisée par l’organisme','Le texte distingue un aliment de certaines substances qu’il apporte.','Aliment et nutriment sont toujours strictement le même objet lexical.','Un aliment peut apporter plusieurs nutriments.'),
 F('carence','un manque d’un élément nécessaire','Le texte emploie carence pour parler d’une insuffisance.','Carence signifie toujours un excès de tout nutriment.','Le sens renvoie à un manque, non à un excès.'),
 F('malnutrition','des insuffisances excès ou déséquilibres nutritionnels','Le résumé distingue plusieurs formes de malnutrition.','Malnutrition signifie uniquement absence totale de nourriture.','Le terme couvre aussi des excès et des déséquilibres.'),
 F('hydratation','l’apport et l’équilibre en eau','L’affiche distingue l’eau des autres thèmes de l’alimentation.','Le mot hydratation établit une quantité universelle pour tous.','La définition ne fixe pas un besoin individuel identique pour chacun.')],
 [('Un manque d’un élément nécessaire est une ___.','carence'),('Une substance utilisée par l’organisme est un ___.','nutriment'),('Les insuffisances, excès ou déséquilibres relèvent du terme ___.','malnutrition'),('L’apport et l’équilibre en eau concernent l’___.','hydratation')],[21,23])

homos=[('Une condition est introduite dans « ___ le groupe est prêt, nous partirons ».','si','une condition'),('Dans « ces livres-___ », on ajoute une particule démonstrative.','ci','une particule liée au démonstratif'),('Le nom de l’outil dans « une ___ » doit être choisi.','scie','un nom d’outil'),('Dans « Bih ___ prépare », on reprend se et le lieu déjà annoncé.','s’y','la suite se plus y')]
def homophone(n,records):
    bank=[]
    for q,r,meaning in records:
        other=[x for x in records if x[1]!=r][:3]
        bank.append(item(q,r,[(rr,'Cette graphie correspond ici à '+m+', pas à la construction demandée.') for qq,rr,m in other], 'Le contexte demande '+meaning+'.'))
    return qa(n,'graphie',2,bank)
unit(7,'Les homophones : si, ci, scie, s’y','choisir une graphie selon sa fonction et le sens de la phrase',
 'les pronoms compléments et les phrases de récit','l’affixation et la relecture d’une narration',
 'Des homophones se ressemblent à l’oral mais s’écrivent différemment selon leur sens et leur fonction. Si peut introduire une condition ; -ci apparaît notamment avec un démonstratif comme ce livre-ci ; scie est ici un nom d’outil ; s’y associe le pronom se élidé et y. Chaque forme a d’autres contextes possibles : la leçon ne réduit pas si à une seule valeur. Pour écrire, analyse la phrase plutôt que de recopier une sonorité imaginée. Cette activité écrite ne vérifie pas une écoute réelle.',
 'Modèles originaux : Si le groupe est prêt, nous partirons. Ces livres-ci sont disponibles. Le mot scie nomme ici un outil, sans consigne de manipulation. Bih connaît le lieu et s’y prépare. Dans le dernier modèle, y reprend un complément annoncé ; l’apostrophe marque l’élision de se.',
 'Cherche une condition, un démonstratif, un nom ou une construction pronominale. Vérifie l’apostrophe et le trait d’union. Réemploie une graphie dans une phrase nouvelle qui rende son sens identifiable. Une bonne réponse à l’écrit ne prouve pas une prononciation ou une audition correcte.',[
 F('si','une graphie introduisant notamment une condition','Si le groupe est prêt introduit ici une condition.','Si est toujours le nom d’un outil.','Le contexte conditionnel distingue cette graphie.'),
 F('ci','une particule présente dans certains démonstratifs','Ces livres-ci comporte un trait d’union avant ci.','Dans ces livres-ci, ci doit s’écrire s’y.','La construction démonstrative demande -ci.'),
 F('scie','le nom d’un outil dans l’emploi étudié','Une scie est un groupe nominal.','Le nom de l’outil s’écrit obligatoirement si.','L’article et le sens du nom orientent la graphie.'),
 F('s’y','la suite de se élidé et du pronom y','Bih s’y prépare reprend une construction pronominale.','S’y est toujours une particule démonstrative après livres.','Il faut reconnaître les pronoms et leur reprise.')],homophone(7,homos),[3,5,6])

forms=[('Il faut qu’il ___ prêt.','{fr2Subjonctif("être",2)}','la forme de être au subjonctif avec il'),('Il faut qu’ils ___ prêts.','{fr2Subjonctif("être",6)}','la forme de être au subjonctif avec ils'),('Ce tissu est en ___.','soie','un nom de matière'),('On garde confiance en ___.','soi','un pronom tonique'),('___ prudent ! On donne un conseil à tu.','{fr2Imperatif("être",0)}','l’impératif de être à la personne de tu')]
unit(26,'Les homophones : soit, soient, soie, soi, sois','choisir entre les graphies en reliant forme verbale nom ou pronom au contexte',
 'les homophones, le subjonctif et la syntaxe des sujets','la traduction et la relecture des productions',
 'Soit, soient et sois peuvent être des formes de être ; la personne et la construction commandent l’écriture. Après il faut qu’il, on trouve soit ; après il faut qu’ils, soient. Sois peut être une forme de tu au subjonctif ou un impératif. Soie est un nom de matière ; soi est un pronom tonique, notamment dans un emploi général avec on. Certains mots, comme soit, ont d’autres fonctions : on se limite ici aux contextes explicitement présentés. Le son seul ne décide pas de la graphie.',
 'Modèles originaux : Il faut {fr2Que(2,fr2Subjonctif("être",2))} prêt et {fr2Que(6,fr2Subjonctif("être",6))} prêts. Le tissu est en soie. On garde confiance en soi. {fr2Imperatif("être",0)} prudent ! La valeur de conseil diffère de la matière et du pronom, même si les graphies se ressemblent à l’oral.',
 'Identifie le sujet du verbe éventuel et l’expression qui le commande. Cherche ensuite si la place exige un nom de matière ou un pronom. Vérifie les marques écrites que l’oral ne distingue pas forcément. Réemploie un modèle dans une phrase originale.',[
 F('forme verbale singulière','une forme de être correspondant au sujet singulier et à la construction','Il faut {fr2Que(2,fr2Subjonctif("être",2))} prêt.','Le sujet il impose ici soient.','Au subjonctif présent, il et ils n’ont pas la même graphie.'),
 F('forme verbale plurielle','la forme soient dans le modèle avec ils','Il faut {fr2Que(6,fr2Subjonctif("être",6))} prêts.','Le sujet ils impose ici la graphie soie.','Soie est un nom de matière, pas la forme verbale demandée.'),
 F('nom de matière','la catégorie de soie dans le groupe en soie','Un tissu en soie contient un nom.','Soie est toujours un pronom reprenant on.','Le contexte du tissu demande la matière.'),
 F('pronom tonique','la catégorie de soi dans un emploi général comme confiance en soi','On garde confiance en soi.','Soi est le nom d’un tissu dans cette phrase.','Le pronom renvoie au sujet dans cette construction générale.')],homophone(26,forms),[7,22,24])

liaisons=[('les amis','liaison [z]','la liaison entre les et amis dans ce groupe nominal'),('un ami','liaison [n]','la liaison entre un et ami dans ce groupe nominal'),('un petit ami','liaison [t]','la liaison de petit avec ami dans ce groupe nominal'),('et elle','aucune liaison à cet endroit','l’absence de liaison après et'),('les héros','aucune liaison à cet endroit','l’absence de liaison devant le h aspiré de héros')]
soundoptions=['liaison [z]','liaison [n]','liaison [t]','aucune liaison à cet endroit']
def liaison_feedback(group,right,option):
    if right.startswith('aucune'):
        return 'Le son '+option.split(' ')[1]+' ajouterait une liaison interdite '+('après la conjonction et.' if group=='et elle' else 'devant le h aspiré de héros.')
    if option.startswith('aucune'):
        return 'Ce choix supprime une liaison attendue dans ce groupe nominal ; la consonne de liaison est '+right.split(' ')[1]+'.'
    return 'Le son '+option.split(' ')[1]+' ne correspond pas à la consonne de liaison de '+group+' ; ce modèle demande '+right.split(' ')[1]+'.'
liaisonq=qa(12,'liaison',2,[item('Modèle écrit à préparer avec un professeur : « '+g+' ». Choisis l’indication à l’endroit étudié.',r,[(o,liaison_feedback(g,r,o)) for o in soundoptions if o!=r],why+'.') for g,r,why in liaisons])
unit(12,'Les liaisons : préparation écrite','repérer des liaisons obligatoires et interdites dans des groupes écrits et les distinguer de l’enchaînement',
 'les sons, les mots et la lecture en groupes','les constructions complexes et une pratique orale guidée',
 'Une liaison fait entendre, dans certains contextes, une consonne finale habituellement muette devant une voyelle initiale ou un h muet. Les modèles les amis, un ami et un petit ami illustrent des sons de liaison différents. On ne fait pas la liaison après et ni devant un h aspiré comme dans héros. D’autres liaisons sont facultatives selon le contexte et le registre. L’enchaînement d’une consonne déjà prononcée, comme dans avec elle, n’est pas le même mécanisme. La graphie seule ne règle pas tous les cas.',
 'Modèles écrits : les amis → [z] entre les mots ; un ami → [n] ; un petit ami → [t]. Et elle et les héros n’ajoutent pas de consonne de liaison aux endroits étudiés. Ce sont des indications à vérifier avec un professeur ou un enregistrement fiable. L’écran ne fournit pas de son et ne peut pas évaluer ta propre réalisation.',
 'Repère la limite des mots et le contexte grammatical. Consulte la prononciation des mots à h aspiré au lieu de deviner. Ne lis pas chaque consonne finale comme si toute frontière imposait une liaison. Prépare un groupe écrit, puis pratique réellement avec un modèle oral.',[
 F('liaison obligatoire','une liaison attendue dans les contextes de référence étudiés','Les amis comporte une liaison [z] entre déterminant et nom.','Les amis demande ici une liaison [t].','La consonne de liaison dépend de la forme et du contexte.'),
 F('liaison interdite','une liaison non réalisée dans les modèles comme et elle','On n’ajoute pas de liaison après et dans et elle.','Et impose toujours une liaison [t] avec le mot suivant.','La conjonction et ne donne pas cette liaison.'),
 F('h aspiré','un début de mot bloquant notamment la liaison dans les modèles étudiés','Les héros ne comporte pas de liaison [z] avant héros.','Tous les mots écrits avec h permettent exactement les mêmes liaisons.','Il faut distinguer h aspiré et h muet.'),
 F('enchaînement','la jonction orale impliquant une consonne déjà prononcée','Le son final de avec reste prononcé dans avec elle.','Toute consonne entendue entre deux mots est forcément ajoutée par liaison.','Une consonne déjà prononcée relève d’un autre mécanisme.')],liaisonq,[7,10,11])

def reading(n,title,goal,back,onward,passage,rows,prereq):
    unit(n,title,goal,back,onward,
      'Comprendre un texte demande de relever les faits, de relier les indices et de distinguer une inférence d’une invention. Une information explicite est écrite ; une inférence s’appuie sur le passage sans prétendre être une citation. L’idée principale rassemble les éléments importants. Si un nom, un prix ou un résultat manque, on le dit au lieu de le deviner. Lis aussi le temps des verbes : une préparation n’est pas le compte rendu d’une action achevée.',passage,
      'Lis l’ensemble, puis retrouve un indice pour chaque réponse. Justifie ce que le passage permet de conclure et nomme ce qu’il ne précise pas. Rédige ensuite une courte phrase originale résumant l’action centrale sans inventer de donnée.',[
      F('information explicite','un renseignement directement indiqué dans le passage','Le lecteur reprend un lieu ou une action effectivement écrit.','Une information explicite est obligatoirement un détail inventé.','Le texte lui-même fournit l’information.'),
      F('inférence justifiée','une conclusion appuyée sur des indices du passage','Le lecteur explique une intention à partir des actions décrites.','Toute supposition est une preuve tirée du texte.','Une conclusion doit rester liée à des indices.'),
      F('idée principale','le sens général rassemblant les actions importantes','Le lecteur résume le problème et la réponse décrite.','Un mot secondaire suffit toujours à résumer tout le passage.','Le résumé doit représenter l’ensemble pertinent.'),
      F('information absente','un renseignement que le passage ne permet pas d’établir','Le lecteur refuse de donner un prix non mentionné.','Une donnée absente devient un fait dès qu’on la devine.','Il faut reconnaître les limites du passage.')],
      choose(n,[(passage+'\n'+q,r,w,e,y) for q,r,w,e,y in rows],key='comprendre'),prereq)

reading(2,'Lire un récit de vie familiale et sociale','repérer une difficulté, une proposition et une information absente dans un récit original',
 'le vocabulaire de la vie familiale et sociale','les reprises pronominales et la construction d’un récit',
 'Texte original : À Bamenda, une famille fictive prépare une visite à la bibliothèque. La tâche de rangement de Bih coïncide avec l’heure du départ. Elle propose de répartir le travail avant de partir. Ayuk demande quelles tâches restent à faire. Un adulte aide le groupe à choisir une organisation. Le texte ne précise ni le nombre de livres empruntés ni le prix d’un transport.',[
 ('Quelle difficulté rencontre Bih ?','Le rangement coïncide avec le départ.',['Tous les livres ont disparu.','La bibliothèque a définitivement fermé.','Le texte affirme que personne ne sait lire.'],['Aucune disparition n’est annoncée.','Aucune fermeture définitive n’est indiquée.','Le texte ne formule pas ce jugement.'],'Le conflit d’horaire est explicitement indiqué.'),
 ('Que propose Bih ?','Répartir le travail avant de partir.',['Abandonner tous les livres.','Inventer le prix d’un trajet.','Accuser une personne sans faits.'],['Elle propose une organisation, pas cet abandon.','Le prix n’est pas donné et n’est pas sa proposition.','Aucune accusation de ce type n’est décrite.'],'La proposition répond à la difficulté.'),
 ('Quel rôle l’adulte joue-t-il dans le passage ?','Il aide à choisir une organisation.',['Il annonce le prix du transport.','Il impose un nombre de livres empruntés.','Il détruit la bibliothèque.'],['Le prix reste absent.','Le nombre n’est pas précisé.','Cette action n’apparaît pas.'],'Le texte mentionne une aide à l’organisation.'),
 ('Quelle donnée n’est pas précisée ?','Le prix d’un transport.',['La ville de l’histoire.','La proposition de Bih.','L’aide d’un adulte.'],['Bamenda est nommée.','La répartition du travail est indiquée.','L’aide est explicitement mentionnée.'],'Reconnaître une absence évite l’invention.')],[1])

reading(25,'Lire un texte sur la gestion des déchets','distinguer observations, projet et résultat dans un passage original sur les déchets',
 'le vocabulaire environnemental et le débat argumenté','la traduction et la rédaction de textes précis',
 'Texte original : Dans une école imaginaire de Douala, le club constate que des papiers restent près des salles. Bih propose une affiche expliquant les catégories de la collecte. Ayuk demande de vérifier les consignes avec l’enseignante avant d’installer les boîtes. Le groupe prépare le texte mais n’a pas encore réalisé l’installation. Aucun élève ne doit toucher aux déchets coupants ou inconnus. Le passage ne donne pas le résultat d’une collecte.',[
 ('Quelle observation motive le projet ?','Des papiers restent près des salles.',['L’installation est déjà terminée.','Tous les matériaux sont déjà recyclés.','Aucun papier n’existe dans l’école.'],['L’installation reste à réaliser.','Le recyclage achevé n’est pas affirmé.','Cela contredit l’observation.'],'Le texte part d’un constat précis.'),
 ('Que demande Ayuk avant l’installation ?','Vérifier les consignes avec l’enseignante.',['Toucher aux déchets inconnus.','Annoncer un résultat déjà mesuré.','Ignorer toutes les catégories.'],['La consigne exclut cette manipulation.','Aucun résultat n’est fourni.','Les catégories doivent être expliquées.'],'La vérification précède l’action.'),
 ('Quel état d’avancement est indiqué ?','Le texte est préparé, mais l’installation n’est pas encore réalisée.',['Tout le recyclage est définitivement accompli.','Une collecte mesurée prouve déjà le succès.','Le passage raconte un résultat chiffré.'],['Le projet n’équivaut pas à un recyclage achevé.','Aucune mesure de collecte n’est donnée.','Il ne contient pas ce résultat.'],'Préparation et résultat doivent être distingués.'),
 ('Quelle affirmation dépasse le passage ?','La collecte a déjà prouvé son efficacité.',['Bih propose une affiche.','Ayuk demande une vérification.','Le groupe prépare le texte.'],['La proposition est écrite.','La demande est explicite.','La préparation est indiquée.'],'Un résultat non fourni ne doit pas être ajouté.')],[17,19,24])

imagebank=[]
for key,q,r,w,e,y in [
 ('file','Quelle description et consigne sont compatibles avec la scène ?','On voit des personnes alignées près d’une entrée ; on peut proposer d’attendre son tour.',['On connaît déjà leurs noms et leurs dossiers.','On voit une course et il faut doubler tout le monde.','Le dessin permet d’entendre exactement une conversation.'],['Aucun dossier ni nom n’est fourni.','La file ne justifie pas ce dépassement.','Une image ne fournit pas cet enregistrement.'],'Distingue ce qui est visible de la consigne proposée.'),
 ('silence','Quelle lecture de l’image est justifiée ?','Le livre et le symbole barré près de la bibliothèque suggèrent de parler discrètement.',['L’image prouve que tous les élèves ont échoué.','Le livre signifie qu’il faut jeter les cahiers.','Le symbole prouve le nom de chaque lecteur.'],['Aucun résultat scolaire n’est montré.','Le dessin ne montre pas cette consigne.','Les identités ne sont pas données.'],'Les indices orientent une consigne sans inventer une histoire.'),
 ('tri','Quelle proposition suit les indices visibles ?','Des boîtes portent des catégories ; on peut demander de suivre le tri prévu.',['Les boîtes prouvent que toute matière est déjà recyclée.','Les étiquettes ordonnent de mélanger les catégories.','Le dessin impose de manipuler tout déchet inconnu.'],['Le tri n’est pas la preuve d’une transformation déjà faite.','Les catégories indiquent une séparation.','Une image de classe ne donne pas cette permission.'],'Décris les catégories puis formule une consigne limitée.'),
 ('eau','Quelle interprétation respecte la scène ?','Le robinet et l’indication après lavage suggèrent de le fermer après usage.',['Le dessin donne le diagnostic médical d’un élève.','Le robinet prouve que chaque goutte est potable.','L’image permet de connaître toute la consommation annuelle.'],['Aucun diagnostic n’apparaît.','La potabilité demande d’autres informations.','Aucun relevé annuel n’est donné.'],'La consigne concerne l’usage montré, pas des données absentes.')]:
    row=item(q,r,list(zip(w,e)),y); row['svg']=scene(key); imagebank.append(row)
unit(4,'Préparer une description orale d’images scolaires','décrire les indices d’une scène et proposer une consigne plausible sans inventer de faits',
 'la lecture d’un texte et l’identification d’informations explicites','les consignes, le débat et l’impératif',
 'Décrire une image demande de nommer ce qui est visible : personnages, objets, disposition et symboles. Une interprétation propose un sens à partir d’indices ; elle ne permet pas de connaître une identité, une intention ou une conversation absente. Pour formuler une consigne, choisis un verbe précis et un destinataire adapté. Les scènes sont des dessins originaux de classe. Cette préparation écrite ne mesure ni ta voix ni ton aisance réelle ; une pratique avec un partenaire ou un professeur reste nécessaire.',
 'Modèle original : Des personnes sont alignées près d’une entrée. Je peux décrire leur position, puis proposer : attendons notre tour. Je ne connais pas leurs noms et je n’entends pas leurs paroles. Le passage de l’observation à la consigne doit être expliqué, plutôt que présenté comme une information certaine cachée dans le dessin.',
 'Commence par je vois, puis justifie une interprétation avec un indice. Formule une courte consigne en distinguant proposition et fait observé. Fais ensuite une description orale réelle si un partenaire est disponible ; l’écran ne l’enregistre pas.',[
 F('observation','un élément effectivement visible dans le dessin','Des personnes alignées près d’une porte sont décrites.','Une image donne forcément les noms complets de tous les personnages.','Le visible ne fournit pas automatiquement leur identité.'),
 F('interprétation','un sens proposé à partir des indices','Un symbole barré près d’un livre suggère une consigne de bibliothèque.','Toute interprétation est une certitude sans besoin d’indice.','Il faut relier l’interprétation aux éléments visibles.'),
 F('consigne','une formulation orientant une action','Attendons notre tour propose un comportement adapté à la file.','Une consigne doit toujours porter sur une donnée absente du dessin.','Elle doit répondre à la situation et rester compréhensible.'),
 F('limite du support','ce qu’une image écrite ne permet pas d’établir','Le dessin ne fait pas entendre une conversation.','Répondre à l’écrit prouve une maîtrise orale complète.','Description écrite et performance orale ne sont pas la même évaluation.')],
 qa(4,'image',2,imagebank,figure='X.svg'),[2,3],figure=json.dumps(scene('file'),ensure_ascii=False))

unit(19,'Préparer un débat sur l’environnement','formuler un avis soutenu par une raison et répondre respectueusement à une objection',
 'le vocabulaire de l’environnement et les expressions de nécessité','la lecture critique et les productions argumentées',
 'Un débat met en relation des positions et leurs raisons. Un argument doit soutenir la proposition ; un exemple l’illustre sans prouver à lui seul une règle universelle. Écouter une objection permet de préciser une condition ou une limite. Une concession reconnaît un point pertinent sans renoncer forcément à toute sa position. Attaquer une personne ne répond pas à son raisonnement. Les échanges ci-dessous préparent le langage du débat, sans évaluer une écoute ou une prise de parole réellement enregistrée.',
 'Dialogue original : Bih propose de réemployer des boîtes propres pour limiter certains achats. Ayuk accepte l’idée mais demande si les boîtes conviennent au rangement prévu. Bih reconnaît cette condition et suggère de vérifier avec l’enseignante. Ils distinguent une préférence, un argument et une condition pratique. Le dialogue ne prouve pas que tout objet peut être réemployé sans examen.',
 'Annonce ton avis, donne une raison liée au sujet et réponds à l’objection précise. Emploie je comprends ce point, cependant pour nuancer si nécessaire. Prépare des tours courts, puis pratique un échange réel avec un partenaire en respectant les règles de la classe.',[
 F('avis','une position proposée sur le sujet','Bih préfère examiner le réemploi de boîtes.','Un avis personnel constitue toujours une preuve générale.','Une position demande un appui pertinent.'),
 F('argument','une raison soutenant la proposition','Limiter certains achats explique l’intérêt proposé.','Une phrase sans rapport suffit à défendre n’importe quelle position.','La raison doit porter sur la proposition discutée.'),
 F('objection','une difficulté ou limite opposée à une proposition','Ayuk demande si les boîtes conviennent réellement.','Une objection doit obligatoirement être une insulte.','Une difficulté peut être discutée sans dégrader la personne.'),
 F('concession','la reconnaissance d’un point pertinent avant de préciser sa position','Bih admet la nécessité d’une vérification.','Reconnaître une limite signifie toujours que tout argument précédent est faux.','Une position peut être précisée sans abandonner tout son fondement.')],
 choose(19,[('On te demande pourquoi réemployer une boîte adaptée. Choisis une raison liée à la proposition.','Cela peut éviter un nouvel achat dans ce cas.',['Parce que tous ceux qui hésitent sont idiots.','Parce que demain est un nom de personne.','Parce que toute boîte règle instantanément tous les problèmes.'],['L’insulte ne justifie pas la proposition.','La phrase n’apporte pas de raison liée.','La généralisation dépasse le cas.'],'Relie bénéfice et situation.'),('On objecte que certaines boîtes sont inadaptées. Choisis une réponse.','Vérifions celles qui conviennent avant de les utiliser.',['Ignorons toute propriété de l’objet.','Toute objection est interdite.','L’insulte prouve que la boîte convient.'],['L’adaptation est précisément la question.','Débattre permet d’examiner les objections.','Une attaque personnelle n’établit pas la propriété.'],'Réponds à la limite soulevée.'),('Choisis une concession suivie d’une précision.','La vérification est nécessaire ; mon idée concerne les boîtes adaptées.',['La vérification est inutile puisque je parle fort.','Tout objet convient parce que je le veux.','Celui qui pose une question ne vaut rien.'],['Le volume ne remplace pas l’examen.','La volonté n’établit pas l’adaptation.','C’est une attaque contre la personne.'],'Reconnais le point pertinent sans élargir ta proposition.'),('Un seul exemple de réemploi réussi permet de conclure quoi ?','Le cas décrit peut fonctionner, sans prouver que tous les objets conviennent.',['Tous les déchets sont désormais recyclés.','Aucune limite ne pourra jamais apparaître.','Tous les matériaux ont la même composition.'],['Le cas ne porte pas sur tout le recyclage.','Un exemple ne supprime pas toutes les limites.','La composition n’est pas établie.'],'Garde une conclusion proportionnée à l’exemple.')]),[4,17,18])

def writing(n,title,goal,back,onward,note,model,method,facts,prompt,checks,prereq):
    unit(n,title,goal,back,onward,note,'Modèle original : '+' '.join(model),method,facts,
      B.WO(f'fr4-{n}-construire',2,['Je prépare un texte adapté au destinataire.','Un paragraphe développe une idée claire.','Les liens rendent le texte compréhensible.','Je relis les accords avant de terminer.'],SRC),prereq,
      paper=dict(vars={},checks=[],prompt=prompt,model=model,checklist=checks))

writing(9,'Raconter et enchaîner les événements','rédiger un court récit original dont les événements et les liens restent cohérents',
 'les temps narratifs et les mots formés par affixation','le passé composé, l’imparfait et la lettre racontant une activité',
 'Un récit situe des personnages, un cadre et des événements. Les connecteurs aident le lecteur à suivre l’ordre et les relations : d’abord, puis et enfin organisent la succession ; parce que explique une cause ; pourtant marque un contraste. Ils ne sont pas interchangeables. Une liste de connecteurs ne remplace pas des actions liées. Choisis un point de vue et conserve les référents des pronoms. Le décor et l’événement peuvent employer des temps différents de façon cohérente.',
 ['Un soir, Bih rangeait les livres du club. D’abord, elle chercha le cahier de prêt, mais il manquait. Elle demanda alors à Ayuk où il l’avait posé. Il montra une étagère voisine. Bih y retrouva le cahier et vérifia les retours. Enfin, le groupe put préparer la séance. La recherche prit du temps ; pourtant, personne n’accusa un camarade sans vérifier.'],
 'Prépare cadre, difficulté, actions et issue. Choisis un connecteur selon la relation voulue, puis relis le temps et les reprises. N’ajoute pas parce que pour une simple succession. Le récit peut être entièrement inventé ; aucun événement privé n’est exigé.',[
 F('cadre','le lieu le moment et les circonstances de l’histoire','Un soir situe l’activité du club.','Un récit doit empêcher le lecteur de situer toute action.','Le cadre aide à comprendre le déroulement.'),
 F('succession','l’ordre des événements dans la narration','D’abord, puis et enfin peuvent organiser la suite.','Parce que signifie toujours exactement ensuite.','Cause et succession sont des relations différentes.'),
 F('cause','une relation expliquant pourquoi un fait se produit','Parce que introduit une explication dans une phrase adaptée.','Tout connecteur peut exprimer n’importe quelle relation sans changer le sens.','Le mot de liaison doit correspondre au lien voulu.'),
 F('cohérence','la continuité des temps référents et actions','Le lecteur peut suivre qui cherche puis retrouve le cahier.','Un personnage peut changer d’identité sans explication à chaque phrase.','Les reprises doivent permettre de suivre la même situation.')],
 'Raconte une difficulté résolue dans un club ou une situation communautaire fictive. Situe le cadre, lie les actions et donne une issue. Emploie des connecteurs adaptés, sans imposer le même temps à tous les verbes.',
 ['Le lecteur suit les personnages et l’ordre des actions.','Chaque connecteur exprime la relation voulue.','Les pronoms, temps, accords et détails restent cohérents.'],[6,7,8])

writing(31,'Rédiger une lettre informelle','écrire une lettre personnelle organisée qui raconte une activité et demande une réponse',
 'la narration, les reprises et l’accord sujet-verbe','les productions autonomes destinées à un lecteur précis',
 'Une lettre informelle s’adresse à une personne connue. Elle comporte un lieu et une date adaptés à la consigne, une formule d’appel, des paragraphes, une formule finale et une signature. Le ton peut être personnel tout en restant clair et respectueux. Précise pourquoi tu écris, développe les nouvelles et indique la réponse souhaitée. Les conventions exactes de présentation doivent suivre celles de la classe. Utilise une adresse et des détails fictifs si nécessaire ; une lettre d’exercice ne doit pas exposer de coordonnées privées.',
 ['Buea, lundi','Chère Amina,','Je t’écris pour raconter la préparation de notre club fictif. Nous avons choisi une lecture commune et réparti les tâches. Je préparais l’affiche pendant qu’Ayuk vérifiait les livres. Ensuite, nous avons relu les consignes ensemble.','J’aimerais connaître ton idée pour une prochaine activité. Quel récit voudrais-tu proposer ? Écris-moi quand tu le pourras.','À bientôt,','Ton amie Bih'],
 'Identifie le destinataire et l’intention. Prépare les paragraphes avant d’ajouter les formules. Vérifie les accords, les pronoms et la cohérence du récit, puis la demande finale. Une bonne formule de politesse ne compense pas des nouvelles ou une demande absentes.',[
 F('formule d’appel','une ouverture adaptée au destinataire','Chère Amina ouvre une lettre personnelle fictive.','Une lettre amicale commence obligatoirement par une accusation.','L’appel établit la relation avec le lecteur.'),
 F('paragraphes','des unités organisant les nouvelles et la demande','La lettre distingue récit de l’activité et question à l’amie.','Tout mélanger sans limites rend toujours le texte plus clair.','L’organisation aide le lecteur à suivre les intentions.'),
 F('réponse souhaitée','ce que la lettre demande au destinataire','Bih demande une idée de récit pour une activité.','Une lettre qui pose une question interdit toute réponse.','La demande guide ce que le lecteur peut répondre.'),
 F('signature','l’identification choisie pour la personne qui écrit','Ton amie Bih ferme le modèle fictif.','La signature doit toujours être une donnée privée réelle.','Une production de classe peut utiliser une identité fictive.')],
 'Écris une lettre informelle à une amie ou un ami fictif. Raconte une activité scolaire ou communautaire, précise un détail intéressant et demande une réponse. Ajoute les éléments de présentation attendus en classe, avec des données imaginaires.',
 ['Mon appel, mon ton et ma fin conviennent au destinataire.','Mes paragraphes racontent clairement l’activité et formulent la demande.','Je vérifie accords, temps, reprises et présentation sans utiliser de coordonnées privées.'],[9,15,28,30])

def translation(n,title,goal,back,onward,model,rows,prereq):
    unit(n,title,goal,back,onward,
      'Traduire demande de conserver le sens, les personnes, les relations et le temps dans une construction naturelle. On ne remplace pas simplement chaque mot anglais par le premier mot français rencontré. Repère qui fait quoi, à qui et quand. Une traduction peut avoir plusieurs formulations justes ; les choix proposés testent ici des contrastes explicitement définis. Les courts textes sources anglais sont nécessaires à l’exercice, tandis que les consignes et les explications restent en français.',model,
      'Lis la source, repère les informations essentielles et rédige une proposition en français. Vérifie ensuite personne, temps et sens. N’ajoute pas un traitement, une identité ou un événement absent. Compare la fidélité du message plutôt que l’identité absolue des mots.',[
      F('fidélité','la conservation des informations et relations du texte source','Une traduction garde qui aide qui dans le modèle.','Traduire autorise à inventer les faits qui plaisent.','Les informations ajoutées sans source changent le message.'),
      F('personne grammaticale','le sujet ou destinataire à conserver dans la traduction','We ne devient pas automatiquement elle.','Chaque pronom anglais peut être remplacé par un sujet français au hasard.','Les référents font partie du sens à préserver.'),
      F('temps et aspect','la manière de situer et présenter l’action à conserver selon le contexte','Un événement accompli n’est pas remplacé sans raison par une habitude actuelle.','Le temps du verbe n’a aucune incidence sur le message.','La situation temporelle contribue à l’information.'),
      F('formulation naturelle','une construction française correcte plutôt qu’un calque mécanique','Une phrase est reformulée avec l’ordre attendu en français.','Une traduction fidèle doit toujours copier chaque ordre de mots anglais.','Les langues peuvent organiser différemment un même sens.')],
      choose(n,rows,key='traduire'),prereq)

translation(11,'Traduire de courts textes familiaux ou communautaires','conserver personnes actions et repères temporels dans une traduction simple vers le français',
 'le vocabulaire familial et le passé composé','les liaisons et la précision syntaxique',
 'Sources originales et modèles : “We help our neighbour.” → {cap(fr2With(4,fr2Present("aider",4)))} notre voisin. “She has finished her letter.” → {cap(fr2PasseCompose("finir",3))} sa lettre. Le modèle garde le sujet et l’action sans inventer un autre destinataire.',[
 ('Traduis : “We help our neighbour.”','{cap(fr2With(4,fr2Present("aider",4)))} notre voisin.',['{cap(fr2With(3,fr2Present("aider",3)))} notre voisin.','{cap(fr2With(4,fr2Present("aider",4)))} notre école.','{cap(fr2PasseCompose("aider",4))} notre voisin.'],['We correspond à nous.','La source nomme un voisin, non une école.','La source donne ici un présent, non cet accompli.'],'Conserve le sujet, l’action et le complément.'),
 ('Traduis : “She has finished her letter.”','{cap(fr2PasseCompose("finir",3))} sa lettre.',['{cap(fr2PasseCompose("finir",6))} sa lettre.','{cap(fr2With(3,fr2Present("finir",3)))} sa lettre.','{cap(fr2PasseCompose("finir",3))} sa maison.'],['She désigne ici elle.','La forme proposée perd le fait accompli du modèle.','Letter signifie ici lettre.'],'Le passé composé convient au modèle accompli.'),
 ('Traduis : “They have arrived.” Le contexte précise un groupe féminin.','{cap(fr2PasseCompose("arriver",7))}.',['{cap(fr2PcNoAgree("arriver",7))}.','{cap(fr2PasseCompose("partir",7))}.','{cap(fr2PasseCompose("arriver",3))}.'],['Avec être, le modèle féminin pluriel exige l’accord.','Arrive n’est pas partir.','Le sujet source est pluriel.'],'Conserve le sujet et l’accord demandé.'),
 ('Traduis : “He speaks to the neighbours.”','Il {fr2Present("parler",2)} aux voisins.',['Il {fr2Present("parler",2)} des voisins.','Nous {fr2Present("parler",4)} aux voisins.','Il {fr2Present("parler",2)} aux livres.'],['To nomme ici les destinataires, non le sujet de la conversation.','He n’est pas nous.','La source nomme des personnes voisines.'],'La préposition conserve la relation de destinataire.')],[1,3,9,10])

translation(27,'Traduire des phrases générales sur la santé','préserver le sens d’un message général de santé sans ajouter de conseil ou diagnostic',
 'le lexique de la santé, de la nutrition et les formes verbales','la description et la lettre claire',
 'Sources originales et modèles : “The nurse is here.” → L’infirmière est ici, dans le contexte féminin précisé. “We have a question.” → Nous {fr2Present("avoir",4)} une question. Le thème de santé ne transforme pas une question de langue en consultation ou en prescription.',[
 ('Traduis : “The nurse is here.” Le contexte précise une infirmière.','L’infirmière {fr2Present("être",3)} ici.',['L’infirmière {fr2Present("être",3)} ailleurs.','Les infirmières {fr2Present("être",7)} ici.','L’enseignante {fr2Present("être",3)} ici.'],['Here signifie ici.','La source est singulière dans ce contexte.','Le métier a changé.'],'Préserve profession, nombre et lieu.'),
 ('Traduis : “We have a question.”','Nous {fr2Present("avoir",4)} une question.',['Elle {fr2Present("avoir",3)} une question.','Nous {fr2Present("avoir",4)} une ordonnance.','Nous {fr2Imparfait("avoir",4)} une question.'],['We renvoie à nous.','Question ne signifie pas ordonnance.','Le modèle est au présent.'],'Ne transforme pas une demande d’information en autre chose.'),
 ('Traduis : “She has arrived at the clinic.”','{cap(fr2PasseCompose("arriver",3))} à la clinique.',['{cap(fr2PcNoAgree("arriver",3))} à la clinique.','{cap(fr2PasseCompose("partir",3))} de la clinique.','{cap(fr2PasseCompose("arriver",6))} à la clinique.'],['Le modèle avec être s’accorde ici au féminin.','Arriver n’est pas partir et la relation de lieu change.','She est singulier et féminin dans ce contexte.'],'Conserve l’événement et son sujet.'),
 ('Traduis : “This text explains a word.”','Ce texte explique un mot.',['Ce texte établit ton diagnostic.','Ce texte prescrit un traitement.','Ce texte décrit obligatoirement ton dossier réel.'],['Un mot expliqué ne donne pas ce diagnostic.','La source ne prescrit rien.','Aucun dossier n’est annoncé.'],'Ne donne pas au texte une portée médicale absente de la source.')],[10,21,24,26])

